function rollRarity(zoneLevel, luckBonus = 0) {
  const roll = Math.random() + luckBonus;
  // Was: tier = min(zoneLevel, 10) — froze drop odds at zone-10 levels forever, so
  // zone 42 and zone 95 rolled identically to zone 10. Rescaled with sqrt so zone 1-10
  // matches the original curve exactly (progress=1 at zone 10), then keeps easing
  // upward smoothly instead of flatlining — by zone 95, legendary climbs to ~16%
  // (from 5.5%) and commons become rare instead of a third of all drops.
  const progress = Math.sqrt(Math.min(zoneLevel, 95) / 10);
  if (roll > 0.995 - (progress * 0.05)) return 'legendary';
  if (roll > 0.95 - (progress * 0.10))  return 'epic';
  if (roll > 0.80 - (progress * 0.15)) return 'rare';
  if (roll > 0.50 - (progress * 0.20))  return 'uncommon';
  return 'common';
}

function generateItem(slot, zoneLevel, forceRarity) {
  const table = LOOT_TABLES[slot === 'ring1' || slot === 'ring2' ? 'ring' : slot];
  if (!table) return null;

  // Find appropriate base item by ilvl
  const candidates = table.filter(i => i.ilvl <= zoneLevel + 2);
  const base = candidates.length > 0 
    ? candidates[Math.floor(Math.random() * candidates.length)]
    : table[0];

  const rarity = forceRarity || rollRarity(zoneLevel);
  const rarityData = ITEM_RARITY[rarity];

  const item = {
    n: base.n,
    slot: slot,
    r: rarity,
    d: base.d || 'A piece of adventuring gear.',
    ...base
  };
  item.ilvl = Math.max(base.ilvl, zoneLevel); // must be set after the spread, or base.ilvl silently overwrites it

  // Scale stats to the actual zone level, not just the base template's original ilvl.
  // The loot table's authored items only go up to ilvl 22 — without this, every drop
  // from a level 23+ zone would silently reuse those same frozen-low stats forever,
  // which is exactly what was making high-level drops feel weak.
  const levelScale = Math.max(1, zoneLevel / Math.max(1, base.ilvl));
  if (levelScale > 1) {
    for (let key of FORGE_STAT_KEYS) {
      if (item[key] !== undefined && key !== 'critChance' && key !== 'lifeSteal' && key !== 'mpRegen' && key !== 'hpRegen' && key !== 'goldFind') {
        item[key] = Math.max(1, Math.round(item[key] * levelScale));
      }
    }
  }

  // Apply rarity multiplier to core stats
  if (item.atk) item.atk = Math.floor(item.atk * rarityData.mult);
  if (item.def) item.def = Math.floor(item.def * rarityData.mult);

  // Roll for prefix
  if (Math.random() < rarityData.prefixChance) {
    const prefixes = Object.keys(ITEM_PREFIXES);
    const pName = prefixes[Math.floor(Math.random() * prefixes.length)];
    const pData = ITEM_PREFIXES[pName];
    item.prefix = pName;
    item.prefixData = pData;
    item.n = pName + ' ' + item.n;
    item[pData.stat] = (item[pData.stat] || 0) + pData.val;
  }

  // Roll for suffix
  if (Math.random() < rarityData.prefixChance * 0.7) {
    const suffixes = Object.keys(ITEM_SUFFIXES);
    const sName = suffixes[Math.floor(Math.random() * suffixes.length)];
    const sData = ITEM_SUFFIXES[sName];
    item.suffix = sName;
    item.suffixData = sData;
    item.n = item.n + ' ' + sName;
    item[sData.stat] = (item[sData.stat] || 0) + sData.val;
  }

  // Calculate sell value
  item.value = Math.floor((item.ilvl * 5 + (rarityData.mult * 10)) * (1 + Math.random() * 0.5));

  // Add sockets for Lv 20+ gear (Phase 2)
  const socketCount = getSocketCount(item.ilvl);
  if (socketCount > 0) {
    item.sockets = new Array(socketCount).fill(null);
    item.d += ' [' + socketCount + ' socket' + (socketCount > 1 ? 's' : '') + ']';
  }

  return item;
}

function getEquippedStats() {
  const stats = { atk: 0, def: 0, str: 0, dex: 0, con: 0, int: 0, wis: 0, cha: 0,
                  fireDmg: 0, iceDmg: 0, lightDmg: 0, voidDmg: 0, arcaneDmg: 0,
                  fireRes: 0, iceRes: 0, lightRes: 0, voidRes: 0, arcaneRes: 0,
                  lifeSteal: 0, critChance: 0, mpRegen: 0, hpRegen: 0, goldFind: 0 };

  for (let slot in G.p.eq) {
    const item = G.p.eq[slot];
    if (!item) continue;
    for (let key in stats) {
      if (item[key]) stats[key] += item[key];
      if (item.socketStats && item.socketStats[key]) stats[key] += item.socketStats[key];
    }
  }
  return stats;
}

function getTotalAC() {
  const eqStats = getEquippedStats();
  const dexMod = DICE.abilityMod(G.p.stats.dex + eqStats.dex);
  let baseAC = 10 + dexMod;
  if (G.p.eq.armor) {
    baseAC = 10 + Math.min(dexMod, 2) + (G.p.eq.armor.def || 0);
  }
  baseAC += eqStats.def;
  const shieldBonus = G.p.buffs.reduce((s, b) => s + (b.def || 0), 0) + getFocusedDefBonus() + getStatBoosterBonus('def');
  return baseAC + shieldBonus;
}

// === FOCUSED BUFF ===
// Ties Focus Mode directly into combat instead of the two systems just running in
// parallel — each completed focus session TODAY adds a small permanent-for-the-day
// ATK/DEF bonus, capped at 5 sessions' worth. Scales with level (like the existing
// Blessed/Guildmaster buffs) so it stays meaningful instead of becoming a flat +1 that
// fades into irrelevance at higher levels. Resets to 0 at the same daily rollover as
// focusMinutesToday.
const FOCUSED_BUFF_MAX_SESSIONS = 5;
const FOCUSED_BUFF_ATK_PER_SESSION = 0.15; // × player level, per session today (capped)
const FOCUSED_BUFF_DEF_PER_SESSION = 0.08;

function getFocusedSessionCount() {
  return Math.min(FOCUSED_BUFF_MAX_SESSIONS, G.p.focusSessionsToday || 0);
}
function getFocusedAtkBonus() {
  const n = getFocusedSessionCount();
  return n > 0 ? Math.ceil(n * FOCUSED_BUFF_ATK_PER_SESSION * G.p.lvl) : 0;
}
function getFocusedDefBonus() {
  const n = getFocusedSessionCount();
  return n > 0 ? Math.ceil(n * FOCUSED_BUFF_DEF_PER_SESSION * G.p.lvl) : 0;
}

function getPlayerAtkBuff() {
  return G.p.buffs.reduce((s, b) => s + (b.atk || 0), 0) + getFocusedAtkBonus() + getStatBoosterBonus('atk');
}

function getStatBoosterBonus(stat) {
  if (G.statBooster && G.statBooster.stat === stat && G.statBooster.expiresAt > Date.now()) return G.statBooster.val;
  return 0;
}

// Migrates a single inventory item from the old t:'wep'/'arm'/'acc'/'pgear' schema to the
// modern slot-based one. Applied to every item on load so gear acquired before this
// session's fixes (sitting unequipped in inventory) doesn't stay permanently broken.
const LEGACY_ACC_SLOT_MAP = {
  "Dryad's Ring": 'ring', 'Planar Lens': 'amulet', 'Luck Charm': 'amulet', 'Ring of Wizardry': 'ring',
  'Vecnas Hand': 'amulet', 'Eye of Vecna': 'amulet', 'Belt of Hill Giant Strength': 'amulet',
  'Gnomish Goggles': 'head', 'Starlight Pendant': 'amulet', "Astronomer's Lens": 'amulet',
  'Cinder Ring': 'ring', 'Equilibrium Stone': 'amulet', 'Depth Charge': 'amulet',
  'Lightning Rod Band': 'ring', 'Absorption Ring': 'ring', 'Infinity Loop': 'ring', 'The Crown of Ends': 'head'
};
const LEGACY_PGEAR_SLOT_MAP = {
  "Joel's Bulwark": 'weapon', "Aisyah's Twin Blades": 'weapon', "Soel's Spirit Bell": 'weapon',
  "Eliz's Serenity Orb": 'amulet', "Zaki's Temper Band": 'ring', "Mezstorm's Conduit": 'amulet',
  "Senedra's Hawkeye Lens": 'ring'
};
function migrateLegacyItem(item) {
  if (!item || item.slot) return item; // already modern, or not an equip item at all
  if (item.t === 'wep') { item.slot = 'weapon'; delete item.t; }
  else if (item.t === 'arm') { item.slot = 'armor'; delete item.t; }
  else if (item.t === 'acc') { item.slot = LEGACY_ACC_SLOT_MAP[item.n] || 'amulet'; delete item.t; }
  else if (item.t === 'pgear') {
    item.slot = LEGACY_PGEAR_SLOT_MAP[item.n] || 'weapon';
    if (item.for) { item.forCompanion = item.for; delete item.for; }
    if (item.mp) { item.hp = (item.hp || 0) + item.mp; delete item.mp; } // companions have no MP stat
    delete item.t;
  }
  return item;
}

// Shared by equipItem/unequipItem and lvlup() — the single canonical formula for San's
// Max HP/MP, so equipment con/int bonuses and Temple Blessed's rank bonus apply
// consistently everywhere, rather than lvlup()'s own +10/level increment silently
// drifting out of sync with the full formula used elsewhere.
function recalcMaxHpMp() {
  const eqStats = getEquippedStats();
  G.p.mhp = Math.floor((80 + (G.p.lvl - 1) * 10 + (eqStats.con * 2)) * (1 + getTempleHpPctBonus()));
  G.p.mmp = 120 + (G.p.lvl - 1) * 15 + (eqStats.int * 2);
}

function equipItem(invIndex) {
  const item = G.p.inv[invIndex];
  if (!item || !item.slot) return;

  const slot = item.slot;
  const slotKey = slot === 'ring' ? (G.p.eq.ring1 ? 'ring2' : 'ring1') : slot;

  // Unequip current
  const old = G.p.eq[slotKey];
  if (old) {
    addI(old);
    lg('Unequipped: ' + old.n);
  }

  // Equip new
  G.p.eq[slotKey] = { ...item };
  G.p.inv.splice(invIndex, 1);
  lg('Equipped: ' + item.n + ' (' + ITEM_RARITY[item.r].name + ')');

  // Recalculate derived stats
  recalcMaxHpMp();
  G.p.hp = Math.min(G.p.hp, G.p.mhp);
  G.p.mp = Math.min(G.p.mp, G.p.mmp);
  render();
}

function unequipItem(slot) {
  const item = G.p.eq[slot];
  if (!item) return;
  addI({ ...item });
  lg('Unequipped: ' + item.n);
  G.p.eq[slot] = null;

  // Recalculate
  recalcMaxHpMp();
  G.p.hp = Math.min(G.p.hp, G.p.mhp);
  G.p.mp = Math.min(G.p.mp, G.p.mmp);

  render();
}

