const TRINKET_SHOP = [
  { n: 'Iron Shield',      atk: 0, def: 3, hp: 20, r: 'common',    price: 30 },
  { n: 'Lucky Charm',      atk: 1, def: 1, hp: 10, r: 'common',    price: 25 },
  { n: "Warrior's Band",   atk: 3, def: 0, hp: 15, r: 'uncommon',  price: 60 },
  { n: 'Guardian Pendant', atk: 0, def: 5, hp: 30, r: 'uncommon',  price: 80 },
  { n: 'Storm Crystal',    atk: 4, def: 2, hp: 10, r: 'rare',      price: 150 },
  { n: 'Phoenix Ember',    atk: 2, def: 2, hp: 50, r: 'rare',      price: 200 },
  { n: 'Void Shard',       atk: 6, def: 0, hp: 20, r: 'epic',      price: 400 },
  { n: 'Celestial Seal',   atk: 3, def: 4, hp: 40, r: 'epic',      price: 500 }
];

function buyTrinket(index) {
  const t = TRINKET_SHOP[index];
  if (!t) return;
  
  // Add haggle for trinkets too
  const aisyah = G.party.find(p => p.on && p.n === 'Aisyah' && p.hp > 0);
  const finalPrice = aisyah ? Math.floor(t.price * 0.9) : t.price;
  
  if (G.p.gold < finalPrice) { lg('Need ' + finalPrice + 'G'); return; }
  
  G.p.gold -= finalPrice;
  const item = {
    n: t.n, slot: 'amulet', q: 1, r: t.r,
    atk: t.atk || 0, def: t.def || 0, hp: t.hp || 0,
    d: '+' + (t.atk || 0) + ' ATK, +' + (t.def || 0) + ' DEF, +' + (t.hp || 0) + ' HP'
  };
  addI(item);
  lg('🎁 Bought ' + t.n + ' for ' + finalPrice + 'G!' + (aisyah ? ' (Aisyah haggled 10% off!)' : ''));
  render();
}

function initPartyGearBonus() {
  if (!G || !G.party) return;
  for (let p of G.party) {
    if (!p.gearBonus) p.gearBonus = { atk: 0, def: 0, hp: 0, mp: 0, spd: 0 };
  }
}

function checkAchievements() {
  let newUnlocks = 0;
  for (let ach of G.achievements) {
    if (ach.done) continue;
    if (ach.secret && !ach.revealed) continue;

    let earned = false;
    switch (ach.t) {
      case 'kills':
        if (G.p.kills >= ach.need) earned = true;
        break;
      case 'boss':
        if ((G.p.bossKills || 0) >= ach.need) earned = true;
        break;
      case 'boss_specific':
        if (G.bestiary[ach.target] && G.bestiary[ach.target].kills >= ach.need) earned = true;
        break;
      case 'level':
        if (G.p.lvl >= ach.need) earned = true;
        break;
      case 'quests':
        if (G.p.quests >= ach.need) earned = true;
        break;
      case 'affinity':
        if (G.affinity[ach.target] && G.affinity[ach.target].val >= ach.need) earned = true;
        break;
      case 'party':
        const unlockedCount = G.party.filter(p => p.on || p.hp > 0).length;
        if (unlockedCount >= ach.need) earned = true;
        break;
      case 'craft':
        if ((G.p.crafts || 0) >= ach.need) earned = true;
        break;
      case 'gold':
        if (G.p.gold >= ach.need) earned = true;
        break;
      case 'survivor':
        if (G.p.survivedCritical || false) earned = true;
        break;
      case 'focus':
        if (G.p.fstreak >= ach.need) earned = true;
        break;
    }

    if (earned) {
      ach.done = true;
      G.p.xp += ach.rw.xp;
      G.p.gold += ach.rw.g;
      lg('🏆 ACHIEVEMENT UNLOCKED: ' + ach.n + '! ' + ach.icon);
      showToast('🏆 Achievement unlocked: ' + ach.n, 'success');
      if (ach.secret) {
        lg('   ' + ach.d);
        ach.revealed = true;
      }
      lvlup();
      newUnlocks++;
    }
  }
  return newUnlocks;
}

function revealSecretAchievements() {
  for (let ach of G.achievements) {
    if (ach.secret && !ach.revealed && !ach.done) {
      if (ach.t === 'affinity' && G.affinity[ach.target] && G.affinity[ach.target].val >= ach.need * 0.5) {
        ach.revealed = true;
        lg('🔓 Secret achievement hint unlocked...');
      }
      if (ach.t === 'boss_specific' && G.p.lvl >= 8) {
        ach.revealed = true;
        lg('🔓 Secret achievement hint unlocked...');
      }
    }
  }
}

function checkAffinityUnlocks(name) {
  const aff = G.affinity[name];
  const defs = G.affinityUnlocks[name];
  if (!aff || !defs) return;
  const member = G.party.find(p => p.n === name);
  if (!member) return;
  member.affinityBonuses = member.affinityBonuses || [];
  for (let u of defs) {
    if (aff.val >= u.th && !member.affinityBonuses.includes(u.id)) {
      member.affinityBonuses.push(u.id);
      applyAffinityUnlockFx(member, u);
      lg('🌟 Affinity ' + u.th + ': ' + name + ' unlocks "' + u.n + '" — ' + u.d + '!');
    }
  }
}

function hasAffinityUnlock(name, id) {
  const m = G.party.find(p => p.n === name);
  return !!(m && m.affinityBonuses && m.affinityBonuses.includes(id));
}

// With affinity uncapped, the bar shows progress toward the next unclaimed tier rather
// than a fixed max. Once every tier is claimed, it just shows full.
function getAffinityBarPct(name) {
  const aff = G.affinity[name];
  const defs = G.affinityUnlocks[name];
  if (!aff || !defs || defs.length === 0) return 0;
  const nextTier = defs.find(u => aff.val < u.th);
  if (!nextTier) return 100;
  const prevTier = [...defs].reverse().find(u => aff.val >= u.th);
  const prevTh = prevTier ? prevTier.th : 0;
  return Math.min(100, Math.max(0, ((aff.val - prevTh) / (nextTier.th - prevTh)) * 100));
}

// A growth ability is "ready" when: the player's level meets its threshold, the member
// is active and alive, and it hasn't already fired once since the last rest.
function isGrowthAbilityReady(name) {
  const def = G.growthAbilities[name];
  if (!def) return false;
  if (G.p.lvl < def.unlockAt) return false;
  const member = G.party.find(p => p.n === name);
  if (!member || !member.on || member.hp <= 0) return false;
  if (G.growthAbilityUsed[def.id]) return false;
  return true;
}

// Call the moment an ability actually fires. Marks it used-this-rest, and on the very
// first trigger ever, reveals its name/description to the log and unlocks it in the
// Party screen — before that, its existence is a complete surprise.
function triggerGrowthAbility(name) {
  const def = G.growthAbilities[name];
  if (!def) return;
  G.growthAbilityUsed[def.id] = true;
  if (!G.discoveredAbilities.includes(def.id)) {
    G.discoveredAbilities.push(def.id);
    lg('✨ HIDDEN ABILITY DISCOVERED: ' + name + ' — ' + def.n + '!');
    lg('   "' + def.d + '"');
  } else {
    lg('✨ ' + name + ' unleashes ' + def.n + '!');
  }
}

// Zaki's Nervous Courage isn't a one-shot resource like the others — it's a live
// condition (last one standing beside San) that can hold or lapse turn to turn, so it's
// checked fresh every time rather than gated by the once-per-rest growthAbilityUsed flag.
function checkZakiCourage() {
  const def = G.growthAbilities.Zaki;
  if (G.p.lvl < def.unlockAt) return false;
  const zaki = G.party.find(p => p.n === 'Zaki');
  if (!zaki || !zaki.on || zaki.hp <= 0) return false;
  if (G.p.hp <= 0) return false;
  const othersStanding = G.party.some(p => p.on && p.n !== 'Zaki' && p.hp > 0);
  if (othersStanding) return false;
  if (!G.discoveredAbilities.includes(def.id)) {
    G.discoveredAbilities.push(def.id);
    lg('✨ HIDDEN ABILITY DISCOVERED: Zaki — ' + def.n + '!');
    lg('   "' + def.d + '"');
  }
  return true;
}

function getAffinityUnlockBonus(type) {
  let bonus = 0;
  for (let m of G.party) {
    if (!m.affinityBonuses) continue;
    for (let id of m.affinityBonuses) {
      const def = (G.affinityUnlocks[m.n] || []).find(u => u.id === id);
      if (def && def.fx[type]) bonus += def.fx[type];
    }
  }
  return bonus;
}

function applyAffinityUnlockFx(member, u) {
  const fx = u.fx;
  if (!member.base) member.base = { mhp: member.mhp, atk: member.atk, def: member.def, spd: member.spd };
  if (fx.hpPct) { member.base.mhp += Math.floor(member.base.mhp * fx.hpPct); }
  if (fx.hp) { member.base.mhp += fx.hp; }
  if (fx.atk) member.base.atk += fx.atk;
  if (fx.def) member.base.def += fx.def;
  if (typeof recalcPartyMember === 'function') recalcPartyMember(member);
}

function updateAffinity(partyMemberName, amount) {
  if (!G.affinity[partyMemberName]) return;
  // Soel's Bonding Catalyst — boosts affinity GAIN itself for every other companion
  // while he's active, matching his established "the space between people" role.
  // Deliberately excludes himself (boosting his own affinity gain would be circular)
  // and only applies to positive gains, not decay.
  if (amount > 0 && partyMemberName !== 'Soel') {
    const soelActive = G.party.some(p => p.n === 'Soel' && p.on && p.hp > 0);
    if (soelActive && G.p.lvl >= SOEL_BONDING_CATALYST_UNLOCK) {
      // The Chosen Family (capstone, auto-granted at 50): the bond deepens further.
      amount = Math.ceil(amount * (G.p.lvl >= LATE_GAME_BONUS_LEVEL ? 1.30 : 1.15));
    }
  }
  G.affinity[partyMemberName].val = Math.max(0, G.affinity[partyMemberName].val + amount);
  G.affinity[partyMemberName].lastInteract = Date.now();
  if (amount > 0) {
    lg('💕 Affinity with ' + partyMemberName + ' +' + amount + ' (' + G.affinity[partyMemberName].val + ')');
  }
  checkAffinityUnlocks(partyMemberName);
  checkAchievements();
  revealSecretAchievements();
  checkAffinityDecay();
}

function checkAffinityDecay() {
  const now = Date.now();
  for (let name in G.affinity) {
    const aff = G.affinity[name];
    const hoursSince = (now - aff.lastInteract) / (1000 * 60 * 60);
    if (hoursSince > 24) {
      const decay = Math.floor(hoursSince / 24) * aff.decayRate * 10;
      aff.val = Math.max(0, aff.val - decay);
      if (decay > 0) {
        lg('💔 ' + name + ' feels neglected. Affinity -' + Math.floor(decay) + ' (' + aff.val + ')');
      }
      aff.lastInteract = now;
    }
  }
}

function getAffinityColor(val) {
  if (val >= 70) return 'affinity-high';
  if (val >= 40) return 'affinity-mid';
  return 'affinity-low';
}

function updateTimedQuests() {
  for (let q of G.quests) {
    if (q.timed && !q.done && !q.expired && q.timer > 0) {
      q.timer--;
      if (q.timer <= 0) {
        q.expired = true;
        lg('⏰ Quest expired: ' + q.n + '!');
      }
    }
  }
}

function getTimerStatus(q) {
  if (!q.timed || q.done || q.expired) return null;
  const pct = (q.timer / q.timerMax) * 100;
  if (q.timer <= 0) return { cls: 'timer-expired', label: 'EXPIRED', pct: 0 };
  if (pct < 25) return { cls: 'timer-urgent', label: q.timer + ' ticks left', pct: pct };
  return { cls: 'timer-ok', label: q.timer + ' ticks left', pct: pct };
}

function triggerSoelCommentary(triggerType) {
  if (!G.party[6].on) return;
  if (G.soelCommentCooldown > 0) { G.soelCommentCooldown--; return; }
  if (Math.random() > 0.35) return;
  const relevant = G.soelCommentary.filter(c => c.trigger === triggerType);
  if (relevant.length === 0) return;
  const comment = relevant[Math.floor(Math.random() * relevant.length)];
  G.lastSoelComment = comment;
  G.soelCommentCooldown = 3;
  lg('🐱 Soel: ' + comment.text);
}

 function checkSoelFortune() {
  const soel = G.party.find(p => p.on && p.n === 'Soel');
  if (!soel || soel.hp <= 0) return;
  if (!G.soelFortuneCooldown) G.soelFortuneCooldown = 0;
  G.soelFortuneCooldown++;
  if (G.soelFortuneCooldown < 3) return;
  G.soelFortuneCooldown = 0;
  if (Math.random() > 0.25) return;
  
  const finds = [
    { type: 'g', amount: 15 + Math.floor(Math.random() * 25), msg: 'Soel paws at a loose stone. ' },
    { type: 'mat', item: 'Astral Dust', q: 1, msg: 'Soel bats at a shimmering dust mote. Astral Dust!' },
    { type: 'mat', item: 'Void Fragment', q: 1, msg: 'Soel hisses at a tear in reality. A Void Fragment falls out!' },
    { type: 'mat', item: 'Planar Essence', q: 1, msg: 'Soel chases an invisible spark. It solidifies into Planar Essence!' },
    { type: 'mat', item: 'Ember Shard', q: 1, msg: 'Soel recoils from a warm pebble. It\'s an Ember Shard!' }
  ];
  const find = finds[Math.floor(Math.random() * finds.length)];
  
  if (find.type === 'g') {
    G.p.gold += find.amount;
    lg('🐱 ' + find.msg + find.amount + 'G found!');
  } else {
    addI({ n: find.item, t: 'mat', q: find.q, r: 'common' });
    lg('🐱 ' + find.msg);
  }
}

function checkNPCUnlocks() {
  for (let npc of G.npcs) {
    if (npc.t === 'trader' && !npc.unlocked && G.p.lvl >= npc.zoneLv) {
      npc.unlocked = true;
      lg('🧳 New trader unlocked: ' + npc.n + ' at ' + npc.zone + '!');
    }
    if (npc.t === 'driver' && !npc.unlocked && G.p.lvl >= npc.zoneLv) {
      npc.unlocked = true;
      lg('🚗 ' + npc.n + ' pulls up out of nowhere. "' + npc.greeting + '"');
    }
    if (npc.t === 'ally' && !npc.unlocked && npc.reqMember) {
      if (G.affinity[npc.reqMember] && G.affinity[npc.reqMember].val >= npc.affinityReq) {
        npc.unlocked = true;
        lg('🌟 ' + npc.n + ' ' + npc.title + ' has joined as an ally!');
      }
    }
    if (npc.t === 'ally' && !npc.unlocked && !npc.reqMember && npc.ul && G.p.lvl >= npc.ul) {
      npc.unlocked = true;
      lg('🌟 ' + npc.n + ' ' + npc.title + ' has joined as an ally!');
    }
  }
  checkGuildRecruitment();
}

function getZulTeleportCost(zoneLv) {
  return Math.max(10, zoneLv * 5);
}

function teleportViaZul(zoneIndex) {
  const zone = G.zones[zoneIndex];
  if (!zone) return;
  const cost = getZulTeleportCost(zone.lv);
  if (G.p.gold < cost) {
    lg('❌ Zul taps the wheel. "Kewangan?" You don\'t have the ' + cost + 'G.');
    return;
  }
  G.p.gold -= cost;
  lg('🚗 Zul drops you at ' + zone.n + ' without another word. (-' + cost + 'G)');
  sc(zoneIndex);
}

function buyFromNPC(npcName, itemIdx) {
  const npc = G.npcs.find(n => n.n === npcName);
  if (!npc || !npc.unlocked || npc.t !== 'trader') return;
  
  const item = npc.stock[itemIdx];
  if (!item) return;
  
  // === AISYAH'S HAGGLE ===
  const aisyah = G.party.find(p => p.on && p.n === 'Aisyah' && p.hp > 0);
  const finalPrice = aisyah ? Math.floor(item.price * 0.9) : item.price;
  
  if (G.p.gold < finalPrice) {
    lg('❌ Not enough gold! ' + item.n + ' costs ' + finalPrice + 'G.');
    return;
  }
  
  G.p.gold -= finalPrice;

  // Start from a full copy of the stock item so ANY field it defines survives the
  // purchase (price/idx aside) — a hardcoded whitelist here previously dropped custom
  // fields like stat/boostVal/mins the moment a new effect type introduced them,
  // which either silently no-op'd the item or crashed useI() outright.
  const { price: _price, ...itemData } = item;
  const boughtItem = {
    ...itemData,
    slot: item.slot || undefined,
    forCompanion: item.forCompanion || undefined,
    q: item.q || 1,
    ilvl: item.ilvl || 1,
    d: item.d || 'A purchased item.'
  };
  // Copy sockets as a fresh array — some traders (Wahyu) sell gear with built-in
  // bonus sockets baked into the stock definition itself, distinct from the normal
  // ilvl-based socket migration. Must clone, not reference, so multiple purchases of
  // the same stock item don't end up sharing one sockets array.
  if (item.sockets !== undefined) boughtItem.sockets = new Array(item.sockets.length).fill(null);
  addI(boughtItem);
  npc.visitCount++;
  lg('🧳 Bought ' + item.n + ' from ' + npc.n + ' for ' + finalPrice + 'G!' + (aisyah ? ' (Aisyah haggled 10% off!)' : ''));

  if (npc.visitCount === 1) {
    lg('   ' + npc.n + ': "Pleasure doing business, mage."');
  }
  render();
}

function sellToAmad(invIndex) {
  const npc = G.npcs.find(n => n.n === 'Amad');
  if (!npc || !npc.unlocked || npc.t !== 'trader') return;
  const item = G.p.inv[invIndex];
  if (!item) return;

  // Calculate sell value: 50% of item value, or base price for materials
  let sellPrice = 0;
  if (item.value) {
    sellPrice = Math.floor(item.value * 0.5);
  } else if (item.t === 'mat') {
    sellPrice = Math.floor((item.ilvl || 1) * 3 + 2);
  } else if (item.t === 'pot' || item.t === 'food' || item.t === 'drink') {
    sellPrice = Math.floor((item.v || 10) * 0.3);
  } else {
    sellPrice = Math.floor((item.ilvl || 1) * 4);
  }
  sellPrice = Math.max(1, sellPrice);

  G.p.gold += sellPrice;
  G.p.inv.splice(invIndex, 1);

  const flavorLines = [
    'Amad inspects the ' + item.n + '. "Ah, this has seen some adventure. I will take it."',
    '"Hmm, a bit worn, but I know a collector who wants this," says Amad.',
    'Amad weighs the ' + item.n + ' in his hand. "Fair trade, friend."',
    '"My cousin in Gadong would pay good money for this," Amad grins.',
    'Amad tucks the ' + item.n + ' under his counter. "Terima kasih!"'
  ];
  const flavor = flavorLines[Math.floor(Math.random() * flavorLines.length)];

  lg('💰 Sold ' + item.n + ' to Amad for ' + sellPrice + 'G!');
  lg('   ' + flavor);
  render();
}

// Returns { index, item, price }[] for gear sitting in the bag that's strictly not worth
// keeping: equipment (not companion-specific gear — that's its own stash below) that's a
// Downgrade or Sidegrade versus whatever's already equipped in that slot. Used by the Sell
// Stash button so a whole run of junk drops can be cleared in one tap.
function getJunkStashItems() {
  const results = [];
  for (let i = 0; i < G.p.inv.length; i++) {
    const item = G.p.inv[i];
    const isEquip = item.slot && item.slot !== 'mat' && item.slot !== 'pot' && item.slot !== 'revive' && item.t !== 'food' && item.t !== 'drink';
    if (!isEquip) continue;
    if (item.forCompanion) continue; // handled by getJunkCompanionGearItems() instead
    const cmp = getEquipComparisonForOwner(item);
    if (!cmp || cmp.better) continue; // keep upgrades and anything that fills an empty slot
    let sellPrice = 0;
    if (item.value) sellPrice = Math.floor(item.value * 0.5);
    else sellPrice = Math.floor((item.ilvl || 1) * 4);
    sellPrice = Math.max(1, sellPrice);
    results.push({ index: i, item, price: sellPrice });
  }
  return results;
}

// Same idea as getJunkStashItems(), but scoped specifically to companion-signature gear
// that's a Downgrade or Sidegrade for whichever companion it's flagged for — a separate
// bucket since these clutter the bag differently (picked up for a specific party member,
// not the player) and deserve their own clearly-labeled stash rather than being buried
// in the general equipment pile.
function getJunkCompanionGearItems() {
  const results = [];
  for (let i = 0; i < G.p.inv.length; i++) {
    const item = G.p.inv[i];
    if (!item.slot || !item.forCompanion) continue;
    const cmp = getEquipComparisonForOwner(item);
    if (!cmp || cmp.better) continue; // keep upgrades and anything that fills an empty slot
    let sellPrice = 0;
    if (item.value) sellPrice = Math.floor(item.value * 0.5);
    else sellPrice = Math.floor((item.ilvl || 1) * 4);
    sellPrice = Math.max(1, sellPrice);
    results.push({ index: i, item, price: sellPrice });
  }
  return results;
}

// Raw material clutter — Herb Bundle, Iron Ore, and the like. Unlike equipment, materials
// have no "better/worse" comparison, so there's no smart filtering here: this is every mat
// currently in the bag, sold in one tap for whoever just wants the pile gone. Recipe
// ingredients are cheap to re-farm, so this is a deliberate "clear it out" action, not a
// selective one — same spirit as Sell Stash, just for the item type that actually piles up
// the fastest and has the least individual identity once you have more than a couple of each.
function getMatStashItems() {
  const results = [];
  for (let i = 0; i < G.p.inv.length; i++) {
    const item = G.p.inv[i];
    if (item.t !== 'mat') continue;
    const sellPrice = Math.max(1, Math.floor((item.ilvl || 1) * 3 + 2));
    results.push({ index: i, item, price: sellPrice * (item.q || 1) });
  }
  return results;
}

function sellStashToAmad() {
  const npc = G.npcs.find(n => n.n === 'Amad');
  if (!npc || !npc.unlocked || npc.t !== 'trader') return;
  const junk = getJunkStashItems();
  if (junk.length === 0) { lg('💰 Nothing in your pack is junk right now.'); return; }

  let total = 0;
  // Remove from highest index down so earlier indices stay valid as we splice
  const sorted = [...junk].sort((a, b) => b.index - a.index);
  for (let entry of sorted) {
    total += entry.price;
    G.p.inv.splice(entry.index, 1);
  }
  G.p.gold += total;
  lg('💰 Sold ' + junk.length + ' junk item' + (junk.length > 1 ? 's' : '') + ' to Amad for ' + total + 'G!');
  lg('   "Clearing out the pack, eh? Terima kasih, San."');
  render();
}

function sellCompanionGearStashToAmad() {
  const npc = G.npcs.find(n => n.n === 'Amad');
  if (!npc || !npc.unlocked || npc.t !== 'trader') return;
  const junk = getJunkCompanionGearItems();
  if (junk.length === 0) { lg('💰 No outgrown companion gear to sell right now.'); return; }

  let total = 0;
  const sorted = [...junk].sort((a, b) => b.index - a.index);
  for (let entry of sorted) {
    total += entry.price;
    G.p.inv.splice(entry.index, 1);
  }
  G.p.gold += total;
  lg('💰 Sold ' + junk.length + ' outgrown companion item' + (junk.length > 1 ? 's' : '') + ' to Amad for ' + total + 'G!');
  lg('   "Your family\'s old gear? I know someone who\'ll want it."');
  render();
}

function sellMatsToAmad() {
  const npc = G.npcs.find(n => n.n === 'Amad');
  if (!npc || !npc.unlocked || npc.t !== 'trader') return;
  const mats = getMatStashItems();
  if (mats.length === 0) { lg('💰 No materials to sell right now.'); return; }

  let total = 0;
  const sorted = [...mats].sort((a, b) => b.index - a.index);
  for (let entry of sorted) {
    total += entry.price;
    G.p.inv.splice(entry.index, 1);
  }
  G.p.gold += total;
  lg('💰 Sold ' + mats.length + ' material stack' + (mats.length > 1 ? 's' : '') + ' to Amad for ' + total + 'G!');
  lg('   "Good, good. Less to carry, more to cook with." Amad laughs.');
  render();
}


// ============================================================
// GAME TIME & DAILY SYSTEM
// ============================================================

function getRealDay() {
  // Local-midnight-based, not raw UTC epoch division. The previous version
  // (Math.floor(Date.now() / 86400000)) rolled over at UTC midnight regardless of the
  // player's own timezone — for someone in UTC+8, that's 8 AM local, not midnight.
  // Depending on when in the day an action happened, "24 hours later" could easily
  // still fall inside the same UTC-day window, making daily resets feel unpredictable.
  // Constructing the date from local year/month/day components (rather than UTC ones)
  // makes the boundary track the player's actual calendar date correctly.
  const now = new Date();
  const localMidnight = new Date(now.getFullYear(), now.getMonth(), now.getDate());
  return Math.floor(localMidnight.getTime() / (1000 * 60 * 60 * 24));
}


const MAX_STREAK_FREEZES = 3; // stockpile cap — earned automatically, never bought

function checkDayAdvance() {
  const realToday = getRealDay();
  
  // First time ever playing
  if (G.lastRealDay === 0) {
    G.lastRealDay = realToday;
    G.gameDay = 1;
    G.lastLoginDay = 1;
    G.loginStreak = 1;
    G.loginClaimed = false;
    G.loginHistory = [1];
    G.longestLoginStreak = 1;
    G.p.focusMinutesToday = 0;
    G.p.focusSessionsToday = 0;
    generateDailyQuests();
    generateDailyEventDeck();
    G.manaSpringUses.day = G.gameDay;
    G.manaSpringUses.count = 0;
    saveGame();
    return;
  }
  
  // Same real day — no advance
  if (realToday === G.lastRealDay) return;
  
  // New real day detected — advance game day
  const daysPassed = realToday - G.lastRealDay;
  G.lastRealDay = realToday;

  // Bank the day that just ended into the weekly focus heatmap before we move on.
  // If more than one real day passed (missed days), those in-between days get a
  // 0-minute entry so the heatmap stays honest about gaps rather than skipping them.
  G.focusHistory = G.focusHistory || [];
  G.focusHistory.push({ day: G.gameDay, minutes: G.p.focusMinutesToday || 0 });
  for (let i = 1; i < daysPassed; i++) {
    G.focusHistory.push({ day: G.gameDay + i, minutes: 0 });
  }
  if (G.focusHistory.length > 30) G.focusHistory = G.focusHistory.slice(-30);

  G.gameDay += daysPassed;

  // Resolve any disciple mentorship outcomes whose delay has now passed.
  checkDiscipleOutcomes();

  // Kindling Commissions reset on a new day — bounded, not accumulating.
  G.kindlingCommissions = { linesToday: 0, checksToday: 0, refreshDay: G.gameDay };

  // Mercenary tier was scaling off a lifetime completed-contract count with no cap and
  // no reset — meaning difficulty only ever ratcheted up, disconnected from actual
  // player level, and got punishing fast for anyone doing this repeatable content
  // often. Resetting daily keeps escalation contained to a single day's grinding.
  if (G.mercenary.completed > 0) {
    lg('📋 Mercenary contracts reset for the day \u2014 tier back to 1.');
    G.mercenary.completed = 0;
  }
  
  // Handle streak
  const missedDays = daysPassed - 1;
  if (missedDays === 0) {
    // Consecutive day
    G.loginStreak = (G.loginStreak || 0) + 1;
    lg('📅 New day! Login streak: ' + G.loginStreak);
    showToast('🎁 New day! Collect your rewards', 'gold');
    // Earn a freeze every 7-day milestone, capped — a small, automatic reward for
    // consistency that also insures the streak against the occasional bad day.
    if (G.loginStreak % 7 === 0 && (G.streakFreezes || 0) < MAX_STREAK_FREEZES) {
      G.streakFreezes = (G.streakFreezes || 0) + 1;
      lg('🧊 Streak Freeze earned! (' + G.streakFreezes + '/' + MAX_STREAK_FREEZES + ')');
      showToast('🧊 Streak Freeze earned!', 'gold');
    }
  } else if ((G.streakFreezes || 0) >= missedDays) {
    // Enough banked freezes to fully cover the gap — streak survives, freezes spent.
    G.streakFreezes -= missedDays;
    G.loginStreak = (G.loginStreak || 0) + 1;
    lg('🧊 Streak Freeze protected you \u2014 ' + missedDays + ' missed day' + (missedDays > 1 ? 's' : '') + ' covered. Streak continues: ' + G.loginStreak + '. (' + G.streakFreezes + ' freeze' + (G.streakFreezes === 1 ? '' : 's') + ' left)');
    showToast('🧊 Streak Freeze used \u2014 streak saved!', 'gold');
  } else {
    // Missed one or more days, not enough freezes banked to cover it
    G.loginStreak = 1;
    lg('📅 New day! Streak reset (missed ' + missedDays + ' day' + (missedDays > 1 ? 's' : '') + ').');
    showToast('🎁 New day! Collect your rewards', 'gold');
  }
  if (!G.loginHistory) G.loginHistory = [];
  G.loginHistory.push(G.gameDay);
  if (G.loginHistory.length > 30) G.loginHistory = G.loginHistory.slice(-30);
  G.longestLoginStreak = Math.max(G.longestLoginStreak || 0, G.loginStreak);
  sendLocalNotification('New Day', 'Your daily reward is ready to collect. Streak: ' + G.loginStreak + '.');
  
  G.lastLoginDay = G.gameDay;
  G.loginClaimed = false;
  G.p.focusMinutesToday = 0;
    G.p.focusSessionsToday = 0;
  generateDailyQuests();
  generateDailyEventDeck();
  saveGame();
}

function claimDailyLoginReward() {
  if (G.loginClaimed) {
    lg('🎁 Already claimed today! Come back tomorrow.');
    return;
  }
  
  const streak = G.loginStreak || 1;
  const rewards = [
    { day: 1, g: 50, xp: 25 },
    { day: 2, mp: 30, xp: 35 },
    { day: 3, hp: 50, xp: 45 },
    { day: 4, g: 100, xp: 60 },
    { day: 5, g: 150, xp: 80 },
    { day: 6, mp: 50, xp: 100 },
    { day: 7, g: 300, xp: 200, item: { n: 'Phoenix Feather', t: 'revive', eff: 'revive', v: 50, q: 1, r: 'rare' } }
  ];
  
  const reward = rewards[Math.min(streak - 1, 6)];
  
  if (reward.g) G.p.gold += reward.g;
  if (reward.xp) G.p.xp += reward.xp;
  if (reward.hp) G.p.hp = Math.min(G.p.mhp, G.p.hp + reward.hp);
  if (reward.mp) G.p.mp = Math.min(G.p.mmp, G.p.mp + reward.mp);
  if (reward.item) addI({ ...reward.item });
  
  G.loginClaimed = true;
  saveGame();
  
  const rewardMsg = [];
  if (reward.g) rewardMsg.push('+' + reward.g + 'G');
  if (reward.xp) rewardMsg.push('+' + reward.xp + 'XP');
  if (reward.hp) rewardMsg.push('+' + reward.hp + 'HP');
  if (reward.mp) rewardMsg.push('+' + reward.mp + 'MP');
  if (reward.item) rewardMsg.push(reward.item.n);
  
  lg('🎁 Day ' + streak + ' reward claimed! ' + rewardMsg.join(', '));
  lvlup();
  render();
}

