function generateDailyEventDeck() {
  if (G.eventDeckSeed === G.gameDay && G.dailyEventDeck && G.dailyEventDeck.length > 0) return; // already generated today
  G.eventDeckSeed = G.gameDay;
  const pool = [...EVENT_DECK];
  G.dailyEventDeck = [];
  for (let i = 0; i < DAILY_EVENT_DECK_SIZE && pool.length > 0; i++) {
    const idx = Math.floor(Math.random() * pool.length);
    G.dailyEventDeck.push(pool.splice(idx, 1)[0].id);
  }
  G.eventDeckProgress = {};
  G.activeEventId = null;
}

function openEvent(eventId) {
  G.activeEventId = eventId;
  render();
}

function backToEventDeck() {
  G.activeEventId = null;
  render();
}

function resolveEventChoice(eventId, choiceKey) {
  const eventDef = EVENT_DECK.find(e => e.id === eventId);
  if (!eventDef || (G.eventDeckProgress && G.eventDeckProgress[eventId])) return; // already resolved
  const choice = choiceKey === 'A' ? eventDef.choiceA : eventDef.choiceB;

  let success = true;
  let resultText, xp, g;

  if (choiceKey === 'A') {
    resultText = null; // safe choice has no branching narration, just the flat reward
    xp = choice.baseXp;
    g = choice.baseG;
  } else {
    const eqStats = getEquippedStats();
    const roll = DICE.d(20) + DICE.abilityMod(G.p.stats[choice.stat] + (eqStats[choice.stat] || 0));
    success = roll >= choice.dc;
    resultText = success ? choice.successText : choice.failText;
    xp = choice.baseXp + (success ? choice.bonusXp : 0);
    g = choice.baseG + (success ? choice.bonusG : 0);
  }

  xp = Math.floor(xp * getPrestigeXpMult() * getExpBoosterMult() * (1 + getAllyXpBonus()));
  g = Math.floor(g * getPrestigeGoldMult());
  G.p.xp += xp;
  G.p.gold += g;

  G.eventDeckProgress = G.eventDeckProgress || {};
  G.eventDeckProgress[eventId] = { choiceLabel: choice.label, success, resultText, xp, g };
  lg('📖 ' + eventDef.title + ': +' + xp + ' XP, +' + g + 'G');
  lvlup();
  saveGame();
  render();
}

// === RUNE VAULT ===
// A genuinely different interaction, not another menu of buttons or a stat check — an
// actual short memory-match minigame. One free play per day, resolves in well under a
// minute, reward tier is entirely skill-based (fewer moves = better tier), nothing to
// grind since there's only one attempt available per day.
const RUNE_SYMBOLS = ['🔥', '💧', '🌪️', '⚡', '🌙', '✨'];
const RUNE_VAULT_TIERS = [
  { maxMoves: 8, tier: 'Gold', xp: 400, g: 250 },
  { maxMoves: 11, tier: 'Silver', xp: 250, g: 150 },
  { maxMoves: Infinity, tier: 'Bronze', xp: 130, g: 80 }
];

function isRuneVaultAvailableToday() {
  return (G.runeVault.lastPlayedDay || -1) !== G.gameDay;
}

function startRuneVault() {
  if (!isRuneVaultAvailableToday()) { lg('🔒 Already played the Rune Vault today \u2014 back tomorrow.'); return; }
  const deck = [...RUNE_SYMBOLS, ...RUNE_SYMBOLS]
    .map(symbol => ({ symbol, flipped: false, matched: false }))
    .sort(() => Math.random() - 0.5);
  G.runeVault.cards = deck;
  G.runeVault.flippedIndices = [];
  G.runeVault.moves = 0;
  G.runeVault.active = true;
  G.runeVault.completed = false;
  G.state = 'rune_vault';
  render();
}

function flipRuneCard(idx) {
  const rv = G.runeVault;
  if (!rv.active || rv.flippedIndices.length >= 2) return;
  const card = rv.cards[idx];
  if (!card || card.flipped || card.matched) return;

  card.flipped = true;
  rv.flippedIndices.push(idx);
  render();

  if (rv.flippedIndices.length === 2) {
    rv.moves++;
    const [i1, i2] = rv.flippedIndices;
    if (rv.cards[i1].symbol === rv.cards[i2].symbol) {
      rv.cards[i1].matched = true;
      rv.cards[i2].matched = true;
      rv.flippedIndices = [];
      if (rv.cards.every(c => c.matched)) {
        finishRuneVault();
      } else {
        render();
      }
    } else {
      setTimeout(() => {
        rv.cards[i1].flipped = false;
        rv.cards[i2].flipped = false;
        rv.flippedIndices = [];
        render();
      }, 700);
    }
  }
}

function finishRuneVault() {
  const rv = G.runeVault;
  const result = RUNE_VAULT_TIERS.find(t => rv.moves <= t.maxMoves);
  const xp = Math.floor(result.xp * getPrestigeXpMult() * getExpBoosterMult() * (1 + getAllyXpBonus()));
  const g = Math.floor(result.g * getPrestigeGoldMult());
  G.p.xp += xp;
  G.p.gold += g;
  rv.active = false;
  rv.completed = true;
  rv.resultTier = result.tier;
  rv.resultXp = xp;
  rv.resultG = g;
  rv.lastPlayedDay = G.gameDay;
  lg('🔮 Rune Vault cleared in ' + rv.moves + ' moves \u2014 ' + result.tier + '! +' + xp + ' XP, +' + g + 'G');
  lvlup();
  saveGame();
  render();
}


function generateDailyQuests() {
  // Only regenerate if it's a new game day
  if (G.dailyQuestSeed === G.gameDay && G.dailyQuests && G.dailyQuests.length > 0) {
    return; // Already have quests for today
  }
  
  G.dailyQuestSeed = G.gameDay;
  G.dailyQuests = [];
  G.dailyZonesVisited = []; // reset for Explorer's "2 different zones" tracking

  // Rest & Recover is guaranteed every day rather than competing for one of the 3
  // random slots below — it's simple enough (and its own daily reset flags depend on
  // it enough elsewhere) that it shouldn't be possible to just never see it that day.
  const restTemplate = DAILY_QUESTS.find(t => t.id === 'dq5');
  if (restTemplate) {
    G.dailyQuests.push({
      id: restTemplate.id, n: restTemplate.n, d: restTemplate.d, t: restTemplate.t,
      c: 0, need: restTemplate.need, rw: restTemplate.rw, done: false
    });
  }

  const pool = DAILY_QUESTS.filter(t => t.id !== 'dq5');
  for (let i = 0; i < 3 && pool.length > 0; i++) {
    const idx = Math.floor(Math.random() * pool.length);
    const template = pool.splice(idx, 1)[0];
    G.dailyQuests.push({
      id: template.id, n: template.n, d: template.d, t: template.t,
      c: 0, need: template.need, rw: template.rw, done: false
    });
  }
  lg('📋 New daily quests available for Day ' + G.gameDay + '!');
}

function checkDailyQuests(type, amount) {
  amount = amount || 1;
  if (!G.dailyQuests || G.dailyQuests.length === 0) return;
  for (let q of G.dailyQuests) {
    if (q.done) continue;
    if (q.t === type || (type === 'kill_specific' && q.t === 'kill')) {
      q.c += amount;
      if (q.c >= q.need) {
        q.done = true;
        G.p.xp += q.rw.xp;
        G.p.gold += q.rw.g;
        lg('📋 Daily quest complete: ' + q.n + '! +' + q.rw.xp + 'XP +' + q.rw.g + 'G');
        lvlup();
      }
    }
  }
  saveGame();
}

function refreshBounties() {
  refreshStrongholdTasks();
  refreshGuildContracts();
  checkStrongholdSiege();
  const today = G.gameDay;
  let refreshed = false;

  const eligible = G.bounties.filter(b => {
    if (!b.done || b.refreshDay === today) return false;
    const minLv = b.minLv || 1;
    const maxLv = b.maxLv || 99;
    return G.p.lvl >= minLv && G.p.lvl <= maxLv;
  }).sort((a, b) => Math.abs((a.minLv || 1) - G.p.lvl) - Math.abs((b.minLv || 1) - G.p.lvl));

  if (eligible.length === 0) {
    const fallback = G.bounties.filter(b => {
      if (!b.done || b.refreshDay === today) return false;
      const minLv = b.minLv || 1;
      const maxLv = b.maxLv || 99;
      return minLv <= G.p.lvl && G.p.lvl <= maxLv;
    }).sort((a, b) => (b.minLv || 1) - (a.minLv || 1));
    
    const toRefresh = fallback.slice(0, 3);
    for (let b of toRefresh) {
      b.done = false;
      b.c = 0;
      b.refreshDay = today;
      refreshed = true;
    }
  } else {
    const toRefresh = eligible.slice(0, 3);
    for (let b of toRefresh) {
      b.done = false;
      b.c = 0;
      b.refreshDay = today;
      refreshed = true;
    }
  }

  if (refreshed) {
    lg('📋 New bounties available for Day ' + today + '!');
  }
}


function checkJournalLevelUnlocks() {
  for (let entry of G.storyJournal.entries) {
    if (entry.unlockType === 'level' && G.p.lvl >= entry.unlockAt && !G.storyJournal.unlocked.includes(entry.id)) {
      G.storyJournal.unlocked.push(entry.id);
      G.sessionRecap.chapters.push(entry.title);
      lg('📖 Journal unlocked: ' + entry.title + '!');
      showToast('📖 New story chapter unlocked!', 'gold');
    }
  }
}

function checkStoryline() {
  for (let s of G.storyline) {
    if (s.done) continue;
    if (!s.unlocked) {
      // Check if previous chapter is done
      const prev = G.storyline.find(ch => ch.chapter === s.chapter - 1);
      if (!prev || prev.done) {
        s.unlocked = true;
        lg('📖 Storyline unlocked: Chapter ' + s.chapter + ' - ' + s.n + '!');
        showToast('📖 New story chapter unlocked!', 'gold');
      }
    }
    if (s.unlocked && G.p.lvl >= s.need) {
      s.c = s.need;
      s.done = true;
      G.p.xp += s.rw.xp;
      G.p.gold += s.rw.g;
      G.p.quests++;
      lg('📖 Storyline complete: ' + s.n + '! +' + s.rw.xp + 'XP +' + s.rw.g + 'G');
      lvlup();
    }
  }
}

function checkBountyKill(enemyName, isBossEncounter) {
  checkGuildContractKill(enemyName);

  // boss_specific Guild Contracts — previously only ever checked inline inside the
  // base handleVictory(), so Raid/Boss Rush/Dragon Hunt/Mercenary/Chain Quest/Grind
  // never triggered these at all, only regular exploration combat did.
  if (isBossEncounter && G.guildJoined) {
    for (let c of G.guildContracts) {
      if (c.done) continue;
      if (c.t === 'boss_specific' && enemyName === c.target) completeGuildContract(c);
    }
  }

  // G.quests — same story: kill_specific and boss_specific here were only ever
  // updated inline inside the base handleVictory(), never in any alternate mode.
  for (let q of G.quests) {
    if (q.done) continue;
    if (q.hidden && !q.revealed) continue;
    if (q.t === 'kill_specific' && enemyName === q.target) {
      q.c++;
      lg('📜 ' + q.n + ': ' + q.c + '/' + q.need + ' ' + q.target + ' defeated');
      showToast('📜 ' + q.target + ': ' + q.c + '/' + q.need);
      if (q.c >= q.need) checkQ();
    }
    if (isBossEncounter && q.t === 'boss_specific' && enemyName === q.target) {
      q.c++;
      lg('📜 ' + q.n + ': ' + q.c + '/' + q.need + ' ' + q.target + ' defeated');
      showToast('📜 ' + q.target + ': ' + q.c + '/' + q.need);
      if (q.c >= q.need) checkQ();
    }
  }

  for (let b of G.bounties) {
    if (b.done) continue;
    if (b.t === 'kill_specific' && enemyName === b.target) {
      b.c++;
      if (b.c >= b.need) {
        b.done = true;
        b.refreshDay = G.gameDay;
        G.p.xp += b.rw.xp;
        G.p.gold += b.rw.g;
        G.p.quests++;
        lg('💰 Bounty complete: ' + b.n + '! +' + b.rw.xp + 'XP +' + b.rw.g + 'G');
        showToast('💰 ' + b.n + ' complete!', 'gold');
        lvlup();
      } else {
        showToast('💰 ' + b.target + ': ' + b.c + '/' + b.need);
      }
    }
  }
  for (let t of G.strongholdTasks) {
    if (t.done) continue;
    if (t.t === 'kill_specific' && enemyName === t.target) {
      t.c++;
      if (t.c >= t.need) {
        t.done = true;
        t.refreshDay = G.gameDay;
        G.p.xp += t.rw.xp;
        G.p.gold += t.rw.g;
        lg('🏰 Stronghold task complete: ' + t.n + '! +' + t.rw.xp + 'XP +' + t.rw.g + 'G');
        showToast('🏰 ' + t.n + ' complete!', 'gold');
        lvlup();
      } else {
        showToast('🏰 ' + t.target + ': ' + t.c + '/' + t.need);
      }
    }
  }
}

function getWeaknessMultiplier(spellElem, enemyElem) {
  if (!spellElem || !enemyElem || enemyElem === 'none') return 1;
  // Fire beats Ice, Ice beats Fire
  const elemMult = getTalentMultiplier('elemWeak');
  if (spellElem === 'fire' && enemyElem === 'ice') return 1.5 * elemMult;
  if (spellElem === 'ice' && enemyElem === 'fire') return 1.5 * elemMult;
  // Lightning beats Void
  if (spellElem === 'lightning' && enemyElem === 'void') return 1.5;
  // Arcane beats Void
  if (spellElem === 'arcane' && enemyElem === 'void') return 1.3;
  // Arcane is strong vs arcane (unstable planar energy)
  if (spellElem === 'arcane' && enemyElem === 'arcane') return 1.4;
  // Void consumes arcane
  if (spellElem === 'void' && enemyElem === 'arcane') return 1.3;
  // Same element = reduced damage
  if (spellElem === enemyElem) return 0.5;
  return 1;
}


function getActiveSynergies() {
  const active = G.party.filter(p => p.on && p.hp > 0).map(p => p.n);
  active.push('San');
  const synergies = [];
  for (let syn of G.partySynergies) {
    const allPresent = syn.members.every(m => active.includes(m));
    if (allPresent) synergies.push(syn);
  }
  return synergies;
}

function getSynergyBonus(type) {
  const synergies = getActiveSynergies();
  let bonus = 0;
  for (let syn of synergies) {
    if (syn.bonus[type]) bonus += syn.bonus[type];
  }
  return bonus;
}

function getSynergyDesc() {
  const synergies = getActiveSynergies();
  if (synergies.length === 0) return null;
  return synergies.map(s => s.icon + ' ' + s.name).join(' · ');
}

function applySynergyDamage(dmg, type) {
  const spellBonus = getSynergyBonus('spellDmgPct') + getAffinityUnlockBonus('spellDmgPct');
  if (type === 'spell' && spellBonus > 0) {
    dmg = Math.floor(dmg * (1 + spellBonus));
  }
  return dmg;
}

function applySynergyDefense(dmg) {
  const dmgRed = getSynergyBonus('dmgRed');
  if (dmgRed > 0) {
    dmg = Math.floor(dmg * (1 - dmgRed));
  }
  return Math.max(1, dmg);
}

function getSynergyCritBonus() {
  return getSynergyBonus('critPct') + getAffinityUnlockBonus('critPct');
}

function getSynergyGoldBonus() {
  return getSynergyBonus('goldPct') + getAffinityUnlockBonus('goldPct');
}

function getSynergyHealBonus() {
  return getSynergyBonus('healPct') + getAffinityUnlockBonus('healPct');
}

function getTotalCritChance() {
  // Base 5% + 2% per DEX point + proficiency scaling + synergy bonuses
  const baseCrit = 0.05;
  const dexBonus = G.p.stats.dex * 0.02;
  const profBonus = DICE.proficiencyBonus(G.p.lvl) * 0.01; // +1% per proficiency point
  const synergyBonus = getSynergyCritBonus();
  return Math.min(0.75, baseCrit + dexBonus + profBonus + synergyBonus);
}

function isImmune(enemyName, spellElem) {
  if (!spellElem) return false;
  const fireMobs = ['Fire Imp', 'Lava Slug', 'Ash Wraith'];
  const iceMobs = ['Ice Elemental', 'Frost Wolf', 'Frozen Knight'];
  if (spellElem === 'fire' && fireMobs.includes(enemyName)) return true;
  if (spellElem === 'ice' && iceMobs.includes(enemyName)) return true;
  return false;
}



