function showStory() {
  if(!G.story.active || G.story.shown) return;
  const chapter = G.storyChapters[G.story.chapter];
  if(!chapter) return;
  if(chapter.unlockLevel && G.p.lvl < chapter.unlockLevel) return;
  G.state = 'story';
  render();
}

function advanceStory() {
  const chapter = G.storyChapters[G.story.chapter];
  if(!chapter) { G.story.shown = true; setS('menu'); return; }
  G.story.scene++;
  if(G.story.scene >= chapter.scenes.length) {
    G.story.shown = true;
    G.story.chapter++;
    G.story.scene = 0;
    setS('menu');
  } else {
    render();
  }
}

function checkStoryUnlock() {
  if(G.story.shown) return;
  const nextChapter = G.storyChapters[G.story.chapter];
  if(!nextChapter) return;
  if(nextChapter.unlockLevel && G.p.lvl >= nextChapter.unlockLevel) {
    G.story.shown = false;
    G.story.scene = 0;
    showStory();
  }
}


function rAchievements() {
  let h = '<div class="achievements-view" style="padding:16px;">';
  h += '<h2 class="st">🏆 Achievements</h2>';

  const earned = G.achievements.filter(a => a.done);
  const total = G.achievements.length;
  const secret = G.achievements.filter(a => a.secret);
  const secretEarned = secret.filter(a => a.done);

  h += '<div style="text-align:center;margin-bottom:20px;background:var(--bg-card);border:1px solid var(--border);border-radius:14px;padding:16px;">';
  h += '<div style="font-size:36px;font-weight:700;color:var(--gold);">' + earned.length + '/' + total + '</div>';
  h += '<div style="font-size:12px;color:var(--text-dim);">Achievements Unlocked</div>';
  if (secret.length > 0) {
    h += '<div style="font-size:11px;color:var(--accent-light);margin-top:4px;">🔒 ' + secretEarned.length + '/' + secret.length + ' Secret</div>';
  }
  h += '</div>';

  h += '<div style="display:flex;flex-direction:column;gap:10px;">';
  for (let ach of G.achievements) {
    if (ach.secret && !ach.revealed && !ach.done) {
      h += '<div style="background:var(--bg-card);border:1px solid var(--border);border-radius:14px;padding:14px;display:flex;gap:12px;align-items:center;opacity:0.6;">';
      h += '<div style="font-size:28px;width:40px;text-align:center;">❓</div>';
      h += '<div style="flex:1;">';
      h += '<div style="font-weight:600;font-size:14px;color:var(--text-dim);">Secret Achievement</div>';
      h += '<div style="font-size:11px;color:var(--disabled);">Keep playing to discover...</div>';
      h += '</div></div>';
      continue;
    }

    const done = ach.done;
    h += '<div style="background:var(--bg-card);border:1px solid ' + (done ? 'var(--success)' : 'var(--border)') + ';border-radius:14px;padding:14px;display:flex;gap:12px;align-items:center;' + (done ? 'background:#22c55e10;' : '') + '">';
    h += '<div style="font-size:28px;width:40px;text-align:center;">' + (done ? ach.icon : '🔒') + '</div>';
    h += '<div style="flex:1;">';
    h += '<div style="font-weight:600;font-size:14px;">' + (done ? '✅ ' : '') + ach.n + '</div>';
    h += '<div style="font-size:12px;color:var(--text-dim);line-height:1.4;">' + ach.d + '</div>';
    if (!done) {
      let progress = '';
      switch (ach.t) {
        case 'kills': progress = G.p.kills + '/' + ach.need; break;
        case 'boss': progress = (G.p.bossKills || 0) + '/' + ach.need; break;
        case 'level': progress = G.p.lvl + '/' + ach.need; break;
        case 'quests': progress = G.p.quests + '/' + ach.need; break;
        case 'affinity': progress = (G.affinity[ach.target] ? G.affinity[ach.target].val : 0) + '/' + ach.need; break;
        case 'gold': progress = G.p.gold + '/' + ach.need; break;
        case 'craft': progress = (G.p.crafts || 0) + '/' + ach.need; break;
        case 'focus': progress = G.p.fstreak + '/' + ach.need; break;
        default: progress = '???';
      }
      h += '<div style="font-size:11px;color:var(--accent-light);margin-top:4px;">' + progress + '</div>';
    } else {
      h += '<div style="font-size:11px;color:var(--success);margin-top:4px;">+' + ach.rw.xp + ' XP, +' + ach.rw.g + 'G</div>';
    }
    h += '</div></div>';
  }
  h += '</div></div>';
  return h;
}

function render(){
  // Session Recap takes priority over everything else, including the lightweight
  // AFK bypass paths below — the whole point is surfacing this the moment the user
  // actually returns, which is exactly when AFK mode is most likely to be active.
  if (G.showingSessionRecap) {
    renderSessionRecap();
    return;
  }

  // Boss reveal — a one-time, full-screen "boss appears" moment shown before the
  // fight actually starts, but only for bosses with real custom art. Uses object
  // identity rather than a plain boolean: every combat-start function across every
  // mode (exploration, raid, chain quest, boss rush, dragon hunt, etc.) already
  // creates a fresh G.currentBoss object, so comparing it against the last-revealed
  // reference naturally detects a new fight without touching any of those 8+
  // separate combat-start locations.
  if (G.state === 'combat' && G.currentBoss && bossArtFileName(G.currentBoss.n) && G.currentBoss !== G.bossRevealShownFor) {
    renderBossReveal();
    return;
  }

  // Auto-combat kick-start safety net. toggleAutoCombat() has always explicitly
  // called doAutoCombatTick() the moment it turns auto-combat on — but since
  // auto-combat can now start already-true by default (rather than only being
  // turned on manually), nothing was kicking off the actual tick loop for that
  // case: the flag said "on" but the setTimeout chain never got its first push.
  // Also catches a second, related gap: handleVictory() never resets the heartbeat
  // when a fight cleanly ends, so a brand new fight can inherit a STALE (non-zero
  // but no longer ticking) heartbeat from the previous fight — which fooled this
  // check into thinking the loop was already running, leaving the new fight stuck
  // until the separate watchdog (up to ~6s later) eventually caught it. Checking
  // staleness here too means it self-corrects on the very next render instead.
  if (G.cbt.on && G.cbt.autoCombat && (G.autoCombatHeartbeat === 0 || (Date.now() - G.autoCombatHeartbeat > 4000))) {
    doAutoCombatTick();
  }

  // AFK Grind Mode — bypasses the ENTIRE normal render pipeline (header, HP/MP/XP
  // bars, buffs row, everything) in favor of one tiny status line. Combat logic keeps
  // ticking normally underneath (doAutoCombatTick runs purely on state, never reads
  // the DOM), so this is safe — it just means far less gets repainted every tick,
  // which is the actual point: less work per frame while it runs in the background.
  if (G.grindAfkMode && G.state === 'combat' && G.endlessGrind.active) {
    renderAfkGrindBar();
    return;
  }

  updateMusicForState();

  // AFK Adventure Mode — same idea, but checked on activity alone rather than a
  // specific G.state, since this mode cycles between 'explore' and 'combat' every
  // single encounter (unlike Grind's autoNext, which stays in 'combat' throughout).
  // Without this, the full explore screen would flash back in during every gap.
  // Skipped entirely in "visible" mode — full combat stays on screen the whole time,
  // for actively watching fights rather than a background/AFK loop.
  if (G.afkAdventure.active && !G.afkAdventure.visible) {
    renderAfkAdventureBar();
    return;
  }

  initPartyGearBonus();

  const a=document.getElementById('app'); if(!a)return;
  let h='';
  const prestigeTitle = getPrestigeTitle();
  h+='<div class="hdr"><div class="hdr-l"><div class="hdr-portrait">'+getSpeakerPortrait('San')+'</div><div class="pname">'+G.p.name+' <span class="cls">'+G.p.cls+'</span>'+(prestigeTitle ? ' <span class="cls" style="background:var(--gold);color:#000;">'+prestigeTitle+'</span>' : '')+'</div><div class="lvl">Lv.'+G.p.lvl+'</div></div>';
  h+='<div class="hdr-r">';
  h+='<div class="sb"><div class="sb-row"><span class="si">HP</span><div class="bar"><div class="bf bf-hp" style="width:'+((G.p.hp/G.p.mhp)*100)+'%"></div></div></div><span class="bt">'+G.p.hp+'/'+G.p.mhp+'</span></div>';
  h+='<div class="sb"><div class="sb-row"><span class="si">MP</span><div class="bar"><div class="bf bf-mp" style="width:'+((G.p.mp/G.p.mmp)*100)+'%"></div></div></div><span class="bt">'+G.p.mp+'/'+G.p.mmp+'</span></div>';
  const boosterActive = G.expBooster && G.expBooster.expiresAt > Date.now();
  const boosterMinsLeft = boosterActive ? Math.ceil((G.expBooster.expiresAt - Date.now()) / 60000) : 0;
  h+='<div class="sb"><div class="sb-row"><span class="si">XP</span><div class="bar"><div class="bf bf-xp" style="width:'+((G.p.xp/G.p.xpN)*100)+'%"></div></div></div><span class="bt">'+G.p.xp.toLocaleString()+'/'+G.p.xpN.toLocaleString()+' ('+Math.floor((G.p.xp/G.p.xpN)*100)+'%)'+(boosterActive ? ' <span style="color:var(--gold);">\u26A1+'+Math.floor(G.expBooster.mult*100)+'% '+boosterMinsLeft+'m</span>' : '')+'</span></div>';
  h+='<div class="gold">GOLD: '+G.p.gold+'</div></div></div>';
  if(G.p.buffs.length>0)h+='<div class="buffs">'+G.p.buffs.map(b=>'<span class="bp">'+b.n+' ('+b.t+')</span>').join('')+'</div>';
  if(G.statBooster && G.statBooster.expiresAt>Date.now()){
    const sbMins=Math.ceil((G.statBooster.expiresAt-Date.now())/60000);
    h+='<div class="buffs"><span class="bp" style="background:var(--gold);color:#1a1200;">💊 +'+G.statBooster.val+' '+G.statBooster.stat.toUpperCase()+' ('+sbMins+'m)</span></div>';
  }
  if(G.p.ailments.length>0)h+='<div class="buffs">'+G.p.ailments.map(a=>'<span class="bp" style="background:var(--danger);">'+AILMENT_TYPES[a.type].icon+' '+a.n+'</span>').join('')+'</div>';
  if(G.afkAdventure.active && G.afkAdventure.visible){
    h+='<div style="display:flex;align-items:center;justify-content:space-between;gap:10px;padding:8px 14px;background:rgba(124,58,237,0.15);border-bottom:1px solid var(--accent);font-size:11px;">';
    h+='<span>👁️ Farming ' + G.afkAdventure.zoneIndices.length + ' zone' + (G.afkAdventure.zoneIndices.length > 1 ? 's' : '') + ' \u2014 ' + G.afkAdventure.totalKills + ' kills, +' + G.afkAdventure.totalGold.toLocaleString() + 'G</span>';
    h+='<button onclick="stopAfkAdventure()" style="background:var(--danger);color:white;border:none;border-radius:8px;padding:5px 12px;font-size:11px;font-weight:700;cursor:pointer;flex-shrink:0;">Stop</button>';
    h+='</div>';
  }
  h+='<div class="content">';
  if(G.state=='menu')h+=rMenu();
  else if(G.state=='achievements')h+=rAchievements();
  else if(G.state=='story')h+=rStory();
  else if(G.state=='bestiary')h+=rBestiary();
  else if(G.state=='explore')h+=rExp();
  else if(G.state=='combat')h+=rCbt();
  else if(G.state=='party')h+=rParty();
  else if(G.state=='skills')h+=rSkills();
  else if(G.state=='inventory')h+=rInv();
  else if(G.state=='craft')h+=rCraft();
  else if(G.state=='quest')h+=rQuest();
  else if(G.state=='focus')h+=rFocus();
  else if(G.state=='rest')h+=rRest();
  else if(G.state=='secret')h+=rSecret();
  else if(G.state=='skilltree')h+=rSkillTree();
  else if(G.state=='talents')h+=rTalents();
  else if(G.state=='runes')h+=rRunes();
  else if(G.state=='ministory')h+=rMiniStory();
  else if(G.state=='journal')h+=rJournal();
  else if(G.state=='journalentry')h+=rJournalEntry(G.currentJournalEntry);
  else if(G.state=='npc')h+=rNPC();
  else if(G.state=='grind_room')h+=rGrindRoom();
  else if(G.state=='raid_select')h+=rRaidSelect();
  else if(G.state=='raid_room')h+=rRaidRoom();
  else if(G.state=='guild')h+=rGuild();
  else if(G.state=='stronghold')h+=rStrongholds();
  else if(G.state=='guild_boss')h+=rGuildBoss();
  else if(G.state=='disciples')h+=rDisciples();
  else if(G.state=='party_selection')h+=rPartySelection();
  else if(G.state=='combat_log')h+=rCombatLog();
  else if(G.state=='dragon_hunt')h+=rDragonHunt();
  else if(G.state=='prestige')h+=rPrestige();
  else if(G.state=='boss_rush')h+=rBossRush();
  else if(G.state=='fraying_frontier')h+=rFrayingFrontier();
  else if(G.state=='zone_map_starting_lands')h+=rZoneMapStartingLands();
  else if(G.state=='zone_map_arcane_ascent')h+=rZoneMapArcaneAscent();
  else if(G.state=='zone_map_elemental_wars')h+=rZoneMapElementalWars();
  else if(G.state=='zone_map_aftermath_roads')h+=rZoneMapAftermathRoads();
  else if(G.state=='zone_map_verdant_reach')h+=rZoneMapVerdantReach();
  else if(G.state=='kindling_network')h+=rKindlingNetwork();
  else if(G.state=='boss_rush_room')h+=rBossRushRoom();
  else if(G.state=='fraying_frontier_room')h+=rFrayingFrontierRoom();
  else if(G.state=='guild_war')h+=rGuildWar();
  else if(G.state=='guild_war_room')h+=rGuildWarRoom();
  else if(G.state=='chain_quest')h+=rChainQuest();
  else if(G.state=='event_deck')h+=rEventDeck();
  else if(G.state=='sync')h+=rSyncScreen();
  else if(G.state=='rune_vault')h+=rRuneVault();
  else if(G.state=='forge')h+=rForge();
  else if(G.state=='bonding')h+=rBonding();
  else if(G.state=='mercenary')h+=rMercenary();
  else if(G.state=='afk_adventure')h+=rAfkAdventurePicker();
  else if(G.state=='today')h+=rToday();
  else if(G.state=='bondingscene')h+=rBondingScene();

  h+='</div>';
  h+='<div class="log-panel">'+renderLogPanel()+'</div>';
  h+='<div class="nav"><button class="nb '+(G.state=='menu'?'on':'')+'" data-t="home" data-a="menu">Home</button>';
  h+='<button class="nb '+(G.state=='explore'?'on':'')+'" data-t="exp" data-a="explore">Explore</button>';
  h+='<button class="nb '+(G.state=='party'?'on':'')+'" data-t="party" data-a="party">Party</button>';
  h+='<button class="nb '+(G.state=='quest'?'on':'')+'" data-t="quest" data-a="quest">Quests</button>';
  h+='<button class="nb '+(G.state=='craft'?'on':'')+'" data-t="craft" data-a="craft">Craft</button>';
  h+='<button class="nb '+(G.state=='inventory'?'on':'')+'" data-t="inv" data-a="inventory">Items</button>';
  h+='<button class="nb '+(G.state=='npc'?'on':'')+'" data-t="npc" data-a="npc">Traders</button></div>';
  a.innerHTML=h;
  attachEvents();
  const l=document.getElementById('log'); if(l)l.scrollTop=l.scrollHeight;
}

