function rGrindChampionship() {
  const gc = G.grindChampionship;
  const curIdx = getGrindTierIndex(gc.bestWave);
  const curTier = curIdx >= 0 ? GRIND_TIERS[curIdx] : null;
  const nextTier = GRIND_TIERS[curIdx + 1] || null;

  let h = '<div class="panel panel-gold">';
  h += '<div class="panel-row">';
  h += '<div class="panel-title panel-title-gold">🏆 Grind Championship</div>';
  h += '<div class="btn-hint">Best Wave: <b>' + gc.bestWave + '</b></div>';
  h += '</div>';

  if (curTier) {
    h += '<div class="stat-block">';
    h += '<div class="stat-icon-lg">' + curTier.icon + '</div>';
    h += '<div class="stat-name">' + curTier.name + '</div>';
    h += '<div class="stat-sub stat-sub-accent">Permanent bonus: +' + Math.round(curTier.bonusPct * 100) + '% grind XP/Gold</div>';
    h += '</div>';
  } else {
    h += '<div class="stat-block">';
    h += '<div class="stat-name" style="color:var(--text-dim);">Unranked</div>';
    h += '<div class="stat-sub stat-sub-dim">Reach Wave ' + GRIND_TIERS[0].waveReq + ' to earn your first rank</div>';
    h += '</div>';
  }

  if (nextTier) {
    const prevReq = curTier ? curTier.waveReq : 0;
    const span = nextTier.waveReq - prevReq;
    const progressed = Math.max(0, gc.bestWave - prevReq);
    const pct = Math.min(100, Math.floor((progressed / span) * 100));
    h += '<div class="pbar-label">Next: ' + nextTier.icon + ' ' + nextTier.name + ' (Wave ' + nextTier.waveReq + ')</div>';
    h += '<div class="pbar"><div class="pbar-fill" style="width:' + pct + '%;"></div></div>';
  } else if (curTier) {
    h += '<div class="stat-sub stat-sub-gold" style="text-align:center;">👑 Max League Reached!</div>';
  }

  h += '<div class="icon-row">';
  for (let t of GRIND_TIERS) {
    const claimed = gc.claimedTiers.includes(t.id);
    h += '<span title="' + t.name + ' — Wave ' + t.waveReq + '" class="' + (claimed ? 'icon-earned' : 'icon-locked') + '">' + t.icon + '</span>';
  }
  h += '</div>';

  h += '</div>';
  return h;
}

function rGrindRoom() {
  const g = G.endlessGrind;
  let h = '<div class="content">';
  
  h += '<div class="st" style="text-align:center;">⚔️ Endless Grind Room</div>';
  
  // Stats bar
  const effectiveLv = Math.min(G.p.lvl, g.maxZoneLevel || G.p.lvl, Math.floor(g.wave / 3) + 1);
  h += '<div class="pstat">';
  h += '<span class="mst">Wave: <b>' + g.wave + '</b></span>';
  h += '<span class="mst" title="Enemies this wave are drawn from zones up to this level">Enemy Lv: <b>' + effectiveLv + '</b></span>';
  h += '<span class="mst">Kills: <b>' + g.totalKills + '</b></span>';
  h += '<span class="mst">XP: <b>' + g.totalXp + '</b></span>';
  h += '<span class="mst" style="color:var(--gold)">Gold: <b>' + g.totalGold + '</b></span>';
  h += '</div>';
  
  // Difficulty badge
  const diffClass = { normal: 'sel-normal', hard: 'sel-hard', nightmare: 'sel-nightmare' };
  h += '<div style="text-align:center;margin-bottom:16px;">';
  h += '<span class="badge diff-btn ' + diffClass[g.difficulty] + '" style="display:inline-block;">';
  h += g.difficulty + ' (×' + g.difficultyMult[g.difficulty] + ')</span>';
  h += '</div>';
  
  // === CHAMPIONSHIP LADDER ===
  h += rGrindChampionship();

  // AFK Mode toggle — minimal-render view for multitasking/battery savings
  h += '<div class="panel" style="text-align:center;">';
  h += '<div class="btn-hint" style="margin-bottom:8px;">🔋 AFK Mode: locks the screen to a single status line while auto-combat keeps running \u2014 useful for having this open in the background while you work.</div>';
  h += '<button onclick="startAfkGrind()" class="abtn" style="width:100%;">Enable AFK Mode</button>';
  h += '</div>';

  // MAIN CONTROLS
  if (!g.active) {
    // Between waves or fresh start
    h += '<div class="panel">';
    
    if (g.wave === 0) {
      // FRESH START - show all settings
      h += '<div class="panel-title panel-title-accent" style="margin-bottom:10px;">Grind Settings</div>';
      
      // Tier selector
      h += '<div style="margin-bottom:12px;">';
      h += '<div class="btn-hint" style="margin-bottom:6px;"><b>Max Zone Tier</b> \u2014 which zone level enemies are drawn from. Separate from Difficulty below, which scales stats/rewards on top of whatever tier is picked.</div>';
      h += '<div style="display:flex;gap:6px;flex-wrap:wrap;">';
      const maxTier = G.p.lvl;
      for (let t = 1; t <= maxTier; t++) {
        const z = G.zones.find(zn => zn.lv === t);
        const isSel = g.maxZoneLevel === t;
        h += '<button onclick="setGrindTier(' + t + ')" class="tier-btn' + (isSel ? ' sel' : '') + '" title="' + (z ? z.n : '') + '">Lv.' + t + '</button>';
      }
      h += '</div></div>';
      
      // Difficulty toggle
      h += '<div style="margin-bottom:12px;">';
      h += '<div class="btn-hint" style="margin-bottom:6px;">Difficulty</div>';
      h += '<div style="display:flex;gap:6px;">';
      const diffs = ['normal', 'hard', 'nightmare'];
      for (let d of diffs) {
        const isSel = g.difficulty === d;
        h += '<button onclick="toggleGrindDifficulty()" class="diff-btn' + (isSel ? ' sel-' + d : '') + '">' + d + '</button>';
      }
      h += '</div></div>';
      
      // Auto-next toggle
      h += '<div style="display:flex;align-items:center;gap:8px;margin-bottom:16px;">';
      h += '<input type="checkbox" id="grind-autonext" ' + (g.autoNext ? 'checked' : '') + ' onchange="toggleAutoNext()" style="width:18px;height:18px;accent-color:var(--accent);">';
      h += '<label for="grind-autonext" style="font-size:13px;cursor:pointer;">Auto-start next wave</label>';
      h += '</div>';
      
      h += '<button onclick="enterGrindRoom()" class="abtn" style="width:100%;">Start Grinding</button>';
      
        } else {
      // BETWEEN WAVES - show Next Wave, Stop, and Leave options
      h += '<div class="panel-title panel-title-accent" style="margin-bottom:10px;">Wave ' + g.wave + ' Complete!</div>';
      h += '<div class="btn-hint" style="margin-bottom:16px;">Ready for the next wave?</div>';
      
      h += '<button onclick="startGrindWave()" class="abtn" style="width:100%;margin-bottom:8px;">▶️ Next Wave</button>';
      h += '<button onclick="exitGrindRoom()" class="btn-outline-danger">⏹ Stop & Collect Loot</button>';
      
      // NEW: Leave and reset button
      h += '<button onclick="leaveAndResetGrind()" class="btn-outline-ghost">🚪 Leave Room & Reset (Start Fresh)</button>';
    }
 
    h += '</div>';
    
  } else {
    // ACTIVE COMBAT - show STOP button
    h += '<div class="panel panel-danger">';
    h += '<div class="btn-hint" style="margin-bottom:10px;">Wave ' + g.wave + ' in progress...</div>';
    h += '<button onclick="exitGrindRoom()" class="btn-stop">⏹ STOP GRIND</button>';
    h += '<div class="btn-hint">Returns to camp with current loot</div>';
    h += '</div>';
  }
  
  // Session summary (always visible)
  if (g.wave > 0) {
    h += '<div class="panel">';
    h += '<div class="panel-title panel-title-accent" style="margin-bottom:8px;">📊 This Session</div>';
    h += '<div class="grid2">';
    h += '<div>Started: <span style="color:var(--text-dim);">' + new Date(g.sessionStart).toLocaleTimeString() + '</span></div>';
    h += '<div>Waves: <span style="color:var(--accent-light);">' + g.wave + '</span></div>';
    h += '<div>Total Kills: <span style="color:var(--accent-light);">' + g.totalKills + '</span></div>';
    h += '<div>Total XP: <span style="color:var(--xp);">' + g.totalXp + '</span></div>';
    h += '<div>Total Gold: <span style="color:var(--gold);">' + g.totalGold + '</span></div>';
    h += '<div>Avg/ Wave: <span style="color:var(--text-dim);">' + (g.wave > 0 ? Math.floor(g.totalXp / g.wave) : 0) + ' XP</span></div>';
    h += '</div></div>';
  }
  
  h += '</div>';
  return h;
}

function setGrindTier(tier) {
  G.endlessGrind.maxZoneLevel = tier;
  lg('📍 Max tier set to ' + tier);
  render();
}

function rRaidSelect() {
  let h = '<div class="content">';
  h += '<div class="st" style="text-align:center;">⚔️ Raid Mode</div>';
  h += '<div class="btn-hint" style="text-align:center;margin-bottom:16px;">Boss gauntlets guarded by elite packs. Only ' + Math.round(RAID_STAGE_RECOVERY_PCT * 100) + '% recovery between stages, and raid bosses hit harder than their zone versions. No progress saved mid-raid.</div>';

  for (let raid of RAIDS) {
    const unlocked = isRaidUnlocked(raid);
    const cleared = G.raidProgress.cleared.includes(raid.id);
    const bossCount = raid.stages.filter(s => s.type === 'boss').length;
    const eliteCount = raid.stages.filter(s => s.type === 'elite').length;
    h += '<div class="panel' + (cleared ? ' panel-gold' : '') + '" style="' + (unlocked ? '' : 'opacity:0.55;') + '">';
    h += '<div class="panel-row">';
    h += '<div class="panel-title">' + raid.icon + ' ' + raid.name + (cleared ? ' <span style="color:var(--gold);">✓</span>' : '') + '</div>';
    h += '<div class="btn-hint">Lv.' + raid.unlockLevel + '</div>';
    h += '</div>';
    h += '<div class="btn-hint" style="margin-bottom:8px;">' + raid.desc + '</div>';
    h += '<div style="display:flex;gap:4px;flex-wrap:wrap;margin-bottom:10px;">';
    for (let stage of raid.stages) {
      if (stage.type === 'boss') {
        h += '<span class="badge" style="background:color-mix(in srgb, var(--danger) 15%, transparent);color:var(--danger);">👑 ' + stage.name + '</span>';
      } else {
        h += '<span class="badge" style="background:color-mix(in srgb, var(--el-void) 15%, transparent);color:var(--el-void);">⚔️ Elite Pack</span>';
      }
    }
    h += '</div>';
    if (unlocked) {
      h += '<button onclick="enterRaid(\'' + raid.id + '\')" class="abtn" style="width:100%;">' + (cleared ? 'Raid Again' : 'Begin Raid') + ' (' + bossCount + ' bosses, ' + eliteCount + ' elite packs)</button>';
    } else {
      h += '<div class="btn-hint" style="text-align:center;">🔒 Unlocks at Level ' + raid.unlockLevel + '</div>';
    }
    h += '</div>';
  }

  h += '</div>';
  return h;
}

function rRaidRoom() {
  const raid = getRaidById(G.raid.raidId);
  if (!raid) return '<div class="content"><div class="st">No active raid.</div></div>';
  const nextStage = raid.stages[G.raid.stageIndex];

  let h = '<div class="content">';
  h += '<div class="st" style="text-align:center;">' + raid.icon + ' ' + raid.name + '</div>';

  h += '<div class="panel">';
  h += '<div class="panel-title panel-title-accent" style="margin-bottom:8px;">Stage ' + (G.raid.stageIndex + 1) + ' of ' + raid.stages.length + '</div>';
  h += '<div class="pbar" style="margin-bottom:10px;"><div class="pbar-fill" style="width:' + Math.floor((G.raid.stageIndex / raid.stages.length) * 100) + '%;"></div></div>';
  h += '<div style="display:flex;gap:4px;flex-wrap:wrap;margin-bottom:12px;">';
  for (let i = 0; i < raid.stages.length; i++) {
    const s = raid.stages[i];
    const done = i < G.raid.stageIndex;
    const isNext = i === G.raid.stageIndex;
    const label = s.type === 'boss' ? '👑 ' + s.name : '⚔️ Elite';
    h += '<span class="badge" style="background:' + (done ? 'color-mix(in srgb, var(--success) 20%, transparent)' : isNext ? 'color-mix(in srgb, var(--gold) 20%, transparent)' : 'var(--bg-hover)') + ';color:' + (done ? 'var(--success)' : isNext ? 'var(--gold)' : 'var(--text-dim)') + ';">' + (done ? '✓ ' : '') + label + '</span>';
  }
  h += '</div>';
  const faceLabel = nextStage ? (nextStage.type === 'boss' ? nextStage.name : 'Elite Pack') : '...';
  h += '<button onclick="startRaidStage()" class="abtn" style="width:100%;margin-bottom:8px;">▶️ Face ' + faceLabel + '</button>';
  h += '<button onclick="exitRaid()" class="btn-outline-ghost">🚪 Abandon Raid</button>';
  h += '</div>';

  h += '</div>';
  return h;
}


function rForgeItemRow(ownerName, slot, item) {
  const level = item.upgradeLevel || 0;
  const maxed = level >= FORGE_MAX_LEVEL;
  const cost = maxed ? 0 : FORGE_COSTS[level];
  const needsMendstone = !maxed && (level + 1) === FORGE_MENDSTONE_TIER;
  const hasMendstone = needsMendstone && G.p.inv.some(it => it.n === 'Mendstone');
  const affordable = G.p.gold >= cost && (!needsMendstone || hasMendstone);
  const rarityColor = item.r ? (item.r==='epic'||item.r==='legendary'?'#a855f7':item.r==='rare'?'#3b82f6':item.r==='uncommon'?'#22c55e':'#9ca3af') : '#9ca3af';
  let h = '<div style="background:var(--bg-card);border:1px solid ' + (level > 0 ? 'var(--gold)' : 'var(--border)') + ';border-radius:10px;padding:10px 12px;margin-bottom:6px;">';
  h += '<div style="display:flex;justify-content:space-between;align-items:center;">';
  h += '<div style="font-size:12.5px;font-weight:700;color:' + rarityColor + ';">' + item.n + (level > 0 ? ' <span style="color:var(--gold);">+' + level + '</span>' : '') + '</div>';
  if (maxed) {
    h += '<span class="btn-hint" style="color:var(--gold);">MAX</span>';
  } else {
    h += '<button onclick="forgeUpgradeItem(\'' + ownerName + '\',\'' + slot + '\')" class="abtn' + (affordable ? '' : ' dis') + '" style="margin:0;padding:4px 10px;font-size:11px;">+1 for ' + cost + 'G' + (needsMendstone ? ' + \uD83D\uDC8E' : '') + '</button>';
  }
  h += '</div>';
  if (needsMendstone && !hasMendstone) {
    h += '<div style="font-size:9px;color:var(--text-dim);margin-top:2px;">Requires a Mendstone \u2014 from the Mended Sanctum</div>';
  }
  h += '<div style="font-size:10px;color:var(--text-dim);margin-top:2px;">' + EQUIPMENT_SLOTS[slot]?.name || slot;
  h += '</div></div>';
  return h;
}

function rForge() {
  let h = '<div class="content">';
  h += '<div class="st" style="text-align:center;">⚒️ The Forge</div>';

  const unlocked = isForgeUnlocked();
  h += '<div class="panel' + (unlocked ? ' panel-gold' : '') + '" style="text-align:center;">';
  h += '<div class="panel-title" style="' + (unlocked ? 'color:var(--gold);' : '') + '">Master Kessler, the Forgemaster</div>';
  h += '<div class="btn-hint" style="margin-top:6px;line-height:1.5;">"Bring me what you already carry. I don\'t sell anything \u2014 I just make what\'s yours better." Upgrades any equipped item up to +' + FORGE_MAX_LEVEL + ', each level a straight stat boost. Gold only, except the final tier \u2014 that one also asks for a Mendstone.</div>';
  h += '</div>';

  if (!unlocked) {
    h += '<div class="panel" style="text-align:center;">';
    h += '<div class="btn-hint">🔒 The Forge opens at Level ' + FORGE_UNLOCK_LEVEL + ' (currently Level ' + G.p.lvl + ')</div>';
    h += '</div></div>';
    return h;
  }

  // San's equipped gear
  h += '<div class="panel"><div class="panel-title" style="margin-bottom:8px;">San</div>';
  let anySan = false;
  for (let slot of ['weapon', 'armor', 'head', 'hands', 'feet', 'ring1', 'ring2', 'amulet']) {
    const item = G.p.eq[slot];
    if (!item) continue;
    anySan = true;
    h += rForgeItemRow('San', slot, item);
  }
  if (!anySan) h += '<div class="btn-hint">Nothing equipped yet.</div>';
  h += '</div>';

  // Each active companion's equipped gear
  for (let p of G.party) {
    if (!p.on || !p.eq) continue;
    const slots = Object.keys(p.eq).filter(s => p.eq[s]);
    if (slots.length === 0) continue;
    h += '<div class="panel"><div class="panel-title" style="margin-bottom:8px;">' + p.n + '</div>';
    for (let slot of slots) h += rForgeItemRow(p.n, slot, p.eq[slot]);
    h += '</div>';
  }

  h += '</div>';
  return h;
}

function rWeeklyFocusHeatmap() {
  const hist = (G.focusHistory || []).slice(-6);
  let cells = hist.concat([{ day: G.gameDay, minutes: G.p.focusMinutesToday || 0 }]).slice(-7);
  while (cells.length < 7) cells.unshift({ day: null, minutes: -1 }); // -1 = before the game existed

  const intensity = (m) => {
    if (m < 0) return 'transparent';
    if (m === 0) return 'var(--bg-hover)';
    if (m < 15) return 'rgba(124,58,237,0.35)';
    if (m < 30) return 'rgba(124,58,237,0.6)';
    if (m < 60) return 'rgba(124,58,237,0.85)';
    return 'var(--accent)';
  };
  const totalMin = cells.reduce((s, c) => s + Math.max(c.minutes, 0), 0);

  let h = '<div class="panel">';
  h += '<div class="panel-row"><div class="panel-title">📊 Weekly Focus</div><div class="btn-hint">' + totalMin + 'm this week</div></div>';
  h += '<div style="display:flex;gap:4px;margin-top:8px;">';
  for (let c of cells) {
    h += '<div style="flex:1;height:28px;border-radius:6px;background:' + intensity(c.minutes) + ';display:flex;align-items:center;justify-content:center;font-size:9px;color:var(--text);font-weight:700;">' + (c.minutes > 0 ? c.minutes : '') + '</div>';
  }
  h += '</div></div>';
  return h;
}

function rToday() {
  let h = '<div class="content">';
  h += '<div class="st" style="text-align:center;">📅 Today</div>';
  h += '<div class="btn-hint" style="text-align:center;margin-bottom:16px;">Everything worth a quick look, in one place \u2014 for whenever you\'ve got three minutes and nothing else to point them at.</div>';

  // Notifications toggle — local only (Focus completions, AFK Adventure boss kills),
  // not true push. Nothing can wake this from fully closed without a backend server.
  if (!G.notificationsEnabled) {
    h += '<div class="panel" style="text-align:center;">';
    h += '<div class="btn-hint" style="margin-bottom:8px;">🔔 Get a nudge for Focus completions and AFK Adventure boss kills, even if you\'ve switched apps. Only while this stays open in the background \u2014 not a true push notification.</div>';
    h += '<button onclick="requestNotificationPermission()" class="abtn" style="width:100%;">Enable Notifications</button>';
    h += '</div>';
  }

  // Active siege — most urgent, shown first if present
  for (let id in G.strongholds) {
    if (G.strongholds[id]) h += rSiegeBanner(id);
  }

  // Daily login
  const streakStrip = (G.loginHistory || []).slice(-7).map(() => '🔥').join(' ') || '—';
  const streakStripPad = 7 - (G.loginHistory || []).slice(-7).length;
  const streakStripHTML = streakStrip + (streakStripPad > 0 ? ' ' + '⚪'.repeat(streakStripPad) : '');
  h += '<div class="panel' + (G.loginClaimed ? '' : ' panel-gold') + '">';
  if (!G.loginClaimed) {
    h += '<div class="panel-title" style="color:var(--gold);">🎁 Daily Reward Ready</div>';
    h += '<div class="btn-hint" style="margin:6px 0 4px;">Streak: ' + (G.loginStreak || 1) + ' day' + ((G.loginStreak || 1) > 1 ? 's' : '') + (G.longestLoginStreak > (G.loginStreak || 1) ? ' (best: ' + G.longestLoginStreak + ')' : '') + '</div>';
    h += '<div style="font-size:16px;letter-spacing:2px;margin-bottom:10px;">' + streakStripHTML + '</div>';
    h += '<div class="btn-hint" style="margin-bottom:10px;">🧊 ' + (G.streakFreezes || 0) + '/' + MAX_STREAK_FREEZES + ' Streak Freezes banked \u2014 auto-earned every 7-day streak, auto-used to cover a missed day.</div>';
    h += '<button onclick="claimDailyLoginReward()" class="abtn" style="width:100%;">Claim It</button>';
  } else {
    h += '<div class="panel-row"><div class="panel-title">🔥 Login Streak</div><div class="btn-hint">' + (G.loginStreak || 1) + ' day' + ((G.loginStreak || 1) > 1 ? 's' : '') + (G.longestLoginStreak > (G.loginStreak || 1) ? ' (best: ' + G.longestLoginStreak + ')' : '') + '</div></div>';
    h += '<div style="font-size:16px;letter-spacing:2px;margin:6px 0;">' + streakStripHTML + '</div>';
    h += '<div class="btn-hint" style="margin-bottom:6px;">🧊 ' + (G.streakFreezes || 0) + '/' + MAX_STREAK_FREEZES + ' Streak Freezes banked</div>';
    h += '<div class="btn-hint">Already claimed today. Come back tomorrow.</div>';
  }
  h += '</div>';

  // Quick Focus
  h += '<div class="panel">';
  h += '<div class="panel-title" style="margin-bottom:8px;">🧘 Quick Focus</div>';
  h += '<div class="btn-hint" style="margin-bottom:10px;">One task at a time. Pick a length, start immediately.</div>';
  h += '<div style="display:flex;gap:6px;flex-wrap:wrap;">';
  const focusSessions = [{m:5,xp:20},{m:10,xp:40},{m:15,xp:60},{m:20,xp:80},{m:25,xp:100}];
  for (let s of focusSessions) {
    h += '<button class="focus-session-btn" data-min="' + s.m + '" style="flex:1;min-width:56px;padding:10px 4px;border-radius:10px;border:1px solid var(--accent);background:var(--bg-card);color:var(--text);font-size:12px;font-weight:700;cursor:pointer;text-align:center;">' + s.m + 'm<br><span style="font-size:9px;color:var(--success);font-weight:400;">+' + s.xp + 'XP</span></button>';
  }
  h += '</div></div>';

  // Weekly Focus heatmap — last 7 days at a glance, using the same daily record the
  // Today at a Glance panel reads from. Left-padded with blank cells if the game is
  // younger than a week, so the strip always shows 7 slots.
  h += rWeeklyFocusHeatmap();

  // Mercenary contract
  const contract = getMercenaryContract();
  const mercTier = getMercenaryTier();
  const contractOpponents = Math.max(1, Math.min(3, contract.enemyCount)) + Math.min(3, Math.floor(mercTier / 2)) + 2;
  h += '<div class="panel">';
  h += '<div class="panel-row"><div class="panel-title">📋 ' + contract.title + (mercTier > 0 ? ' <span style="color:var(--gold);">[Tier ' + (mercTier + 1) + ']</span>' : '') + '</div><div class="btn-hint">' + contractOpponents + ' opponents (mage + cleric backed)</div></div>';
  h += '<div class="btn-hint" style="margin:6px 0 10px;">' + contract.flavor + '</div>';
  h += '<button onclick="startMercenaryContract()" class="abtn" style="width:100%;">Take the Job</button>';
  h += '</div>';

  // Daily quests
  if (G.dailyQuests && G.dailyQuests.length > 0) {
    h += '<div class="panel">';
    h += '<div class="panel-title" style="margin-bottom:8px;">📜 Daily Quests</div>';
    for (let q of G.dailyQuests) {
      h += '<div style="display:flex;justify-content:space-between;align-items:center;padding:5px 0;border-bottom:1px solid var(--border);">';
      h += '<span style="font-size:12px;color:' + (q.done ? 'var(--success)' : 'var(--text)') + ';">' + (q.done ? '✓ ' : '') + q.n + '</span>';
      h += '<span style="font-size:11px;color:var(--text-dim);">' + q.c + '/' + q.need + '</span>';
      h += '</div>';
    }
    h += '</div>';
  }

  // Bounties summary
  const activeBounties = G.bounties.filter(b => !b.done && G.p.lvl >= (b.minLv || 1) && G.p.lvl <= (b.maxLv || 99));
  if (activeBounties.length > 0) {
    h += '<div class="panel">';
    h += '<div class="panel-row"><div class="panel-title">💰 Bounties</div><button onclick="setS(\'quest\')" class="btn-hint" style="background:none;border:none;text-decoration:underline;cursor:pointer;">View all</button></div>';
    for (let b of activeBounties.slice(0, 3)) {
      h += '<div style="font-size:12px;color:var(--text-dim);padding:4px 0;">' + b.n + ' \u2014 ' + b.c + '/' + b.need + '</div>';
    }
    h += '</div>';
  }

  // Guild contracts summary
  if (G.guildJoined) {
    const activeContracts = G.guildContracts.filter(c => c.refreshWeek === Math.floor(G.gameDay / 7) && !c.done);
    if (activeContracts.length > 0) {
      h += '<div class="panel">';
      h += '<div class="panel-row"><div class="panel-title">🛡️ Guild Contracts</div><button onclick="setS(\'guild\')" class="btn-hint" style="background:none;border:none;text-decoration:underline;cursor:pointer;">View all</button></div>';
      for (let c of activeContracts.slice(0, 3)) {
        h += '<div style="font-size:12px;color:var(--text-dim);padding:4px 0;">' + c.n + ' \u2014 ' + c.c + '/' + c.need + '</div>';
      }
      h += '</div>';
    }
  }

  h += '</div>';
  return h;
}

function toggleAfkAdventureZone(zi) {
  const idx = G.afkAdventurePicker.indexOf(zi);
  const cap = G.afkAdventureVisibleToggle ? 6 : 3;
  if (idx >= 0) {
    G.afkAdventurePicker.splice(idx, 1);
  } else {
    if (G.afkAdventurePicker.length >= cap) { lg('❌ Up to ' + cap + ' zones at a time.'); return; }
    G.afkAdventurePicker.push(zi);
  }
  render();
}

function toggleAfkAdventureElite() {
  G.afkAdventureEliteToggle = !G.afkAdventureEliteToggle;
  render();
}

function toggleAfkAdventureVisible() {
  G.afkAdventureVisibleToggle = !G.afkAdventureVisibleToggle;
  // Switching modes changes the zone cap (3 background / 6 visible) — trim the
  // selection down if it's now over the new cap rather than leaving it in a state
  // the picker itself wouldn't have allowed.
  const cap = G.afkAdventureVisibleToggle ? 6 : 3;
  if (G.afkAdventurePicker.length > cap) G.afkAdventurePicker = G.afkAdventurePicker.slice(0, cap);
  render();
}

function rAfkAdventurePicker() {
  const visibleMode = G.afkAdventureVisibleToggle;
  const zoneCap = visibleMode ? 6 : 3;
  let h = '<div class="content">';
  h += '<div class="st" style="text-align:center;">🎯 Adventure Farming</div>';

  h += '<button onclick="toggleAfkAdventureVisible()" class="btn-outline-ghost" style="width:100%;text-align:left;margin-bottom:12px;' + (visibleMode ? 'border-color:var(--accent);background:rgba(124,58,237,0.15);' : '') + '">';
  h += (visibleMode ? '👁️ Visible Mode' : '🔋 AFK Mode (Background)');
  h += '<br><span style="font-size:10px;opacity:0.7;">' + (visibleMode ? 'Combat stays on screen the whole time \u2014 up to 6 zones, for actively farming while your phone is in hand.' : 'Minimal screen, saves battery, up to 3 zones \u2014 for while you\'re away or busy.') + '</span>';
  h += '</button>';

  h += '<div class="btn-hint" style="text-align:center;margin-bottom:16px;">Pick up to ' + zoneCap + ' unlocked zones \u2014 the party will auto-explore them on repeat, including their normal boss chance. Good for farming a specific boss or elite a quest needs.</div>';

  h += '<div class="panel">';
  h += '<div class="panel-title" style="margin-bottom:8px;">Selected: ' + G.afkAdventurePicker.length + '/' + zoneCap + '</div>';
  for (let i = 0; i < G.zones.length; i++) {
    const z = G.zones[i];
    if (G.p.lvl < z.lv) continue; // only unlocked zones
    const selected = G.afkAdventurePicker.includes(i);
    const boss = G.bosses.find(b => b.zone === z.n);
    h += '<button onclick="toggleAfkAdventureZone(' + i + ')" class="btn-outline-ghost" style="width:100%;text-align:left;margin-bottom:6px;' + (selected ? 'border-color:var(--accent);background:rgba(124,58,237,0.15);' : '') + '">';
    h += (selected ? '✓ ' : '') + z.n + ' <span style="opacity:0.6;">(Lv.' + z.lv + ')</span>';
    if (boss) h += '<br><span style="font-size:10px;opacity:0.6;">👑 ' + boss.n + '</span>';
    h += '</button>';
  }
  h += '</div>';

  if (G.p.lvl >= ELITE_AFK_UNLOCK_LEVEL) {
    const eliteOn = G.afkAdventureEliteToggle;
    h += '<button onclick="toggleAfkAdventureElite()" class="btn-outline-ghost" style="width:100%;text-align:left;margin-bottom:12px;' + (eliteOn ? 'border-color:var(--gold);background:rgba(251,191,36,0.12);' : '') + '">';
    h += (eliteOn ? '⚡ Elite Mode: ON' : '⚡ Elite Mode: OFF') + '<br><span style="font-size:10px;opacity:0.7;">Tougher enemies (+35% stats), bigger payouts (+50% XP/gold)</span>';
    h += '</button>';
  } else {
    h += '<div class="btn-hint" style="margin-bottom:12px;">🔒 Elite Mode unlocks at Level ' + ELITE_AFK_UNLOCK_LEVEL + '.</div>';
  }

  h += '<button onclick="startAfkAdventure(G.afkAdventurePicker, G.afkAdventureEliteToggle, G.afkAdventureVisibleToggle)" class="abtn" style="width:100%;"' + (G.afkAdventurePicker.length === 0 ? ' disabled' : '') + '>' + (visibleMode ? 'Start Farming' : 'Start AFK Adventure') + '</button>';

  h += '</div>';
  return h;
}

function rMercenary() {
  const contract = getMercenaryContract();
  const mercTier = getMercenaryTier();
  const completed = G.mercenary.completed || 0;
  const intoTier = completed % MERCENARY_CONTRACTS_PER_TIER;
  const tierOpponents = Math.max(1, Math.min(3, contract.enemyCount)) + Math.min(3, Math.floor(mercTier / 2)) + 2;
  let h = '<div class="content">';
  h += '<div class="st" style="text-align:center;">📋 Mercenary Work</div>';
  h += '<div class="btn-hint" style="text-align:center;margin-bottom:16px;">Freelance work never really stopped, apparently \u2014 just the medium changed. Words to swords. Always something available, no setup required.</div>';

  // Tier progress — contracts get harder (and pay better) the more you've cleared.
  h += '<div class="panel">';
  h += '<div class="panel-row"><div class="panel-title">' + (mercTier > 0 ? '🏅 Tier ' + (mercTier + 1) : 'Tier 1') + '</div><div class="btn-hint">' + completed + ' contracts completed</div></div>';
  h += '<div class="qp"><div class="pbar"><div class="pfill" style="width:' + Math.floor((intoTier / MERCENARY_CONTRACTS_PER_TIER) * 100) + '%"></div></div><span class="ptxt">' + intoTier + '/' + MERCENARY_CONTRACTS_PER_TIER + ' to Tier ' + (mercTier + 2) + '</span></div>';
  h += '</div>';

  h += '<div class="panel panel-gold">';
  h += '<div class="panel-title" style="color:var(--gold);">' + contract.title + (mercTier > 0 ? ' [Tier ' + (mercTier + 1) + ']' : '') + '</div>';
  h += '<div class="btn-hint" style="margin:10px 0;line-height:1.6;">' + contract.flavor + '</div>';
  h += '<div class="btn-hint" style="margin-bottom:10px;">' + tierOpponents + ' opponents, mage + cleric backed \u2014 a short, sharp fight.</div>';
  h += '<button onclick="startMercenaryContract()" class="abtn" style="width:100%;">Take the Job</button>';
  h += '<div class="btn-hint" style="text-align:center;margin:10px 0 6px;">Or line up several at once \u2014 auto-combat carries each fight, and the next contract starts on its own when one ends.</div>';
  h += '<div style="display:flex;gap:6px;">';
  for (const n of [5, 10, 25]) {
    h += '<button onclick="startMercenaryBatch(' + n + ')" class="tier-btn" style="flex:1;">Take ' + n + '</button>';
  }
  h += '</div>';
  h += '</div>';

  h += '</div>';
  return h;
}

function rChainQuest() {
  let h = '<div class="content">';
  h += '<div class="st" style="text-align:center;">📜 Chain Quests</div>';
  h += '<div class="btn-hint" style="text-align:center;margin-bottom:16px;">Deliberate descents, not repeatable grinds \u2014 floor by floor, full recovery between each, ending in a payout bigger than anything else in the game. Leave and come back anytime; your floor is saved. Most can be run again once cleared; some are meant to close for good.</div>';

  for (let chain of CHAIN_QUESTS) {
    const unlocked = isChainQuestUnlocked(chain);
    const prog = getChainProgress(chain.id);
    // Scaled floors (rw is null — payout is generated fresh off player level each
    // time) are excluded from this static total rather than crashing the reduce.
    const totalXp = chain.stages.reduce((s, st) => s + (st.rw ? st.rw.xp : 0), 0);
    const totalGold = chain.stages.reduce((s, st) => s + (st.rw ? st.rw.g : 0), 0);
    const hasScaledFloor = chain.stages.some(st => st.type === 'boss_scaled');

    h += '<div class="panel' + (unlocked ? ' panel-gold' : '') + '">';
    h += '<div class="panel-title" style="' + (unlocked ? 'color:var(--gold);' : '') + '">' + chain.icon + ' ' + chain.name + '</div>';

    if (!unlocked) {
      h += '<div class="btn-hint" style="margin:8px 0;">🔒 Unlocks at Level ' + chain.unlockLevel + ' (currently Level ' + G.p.lvl + ')</div>';
      h += '</div>';
      continue;
    }

    if (prog.cleared && chain.repeatable === false) {
      h += '<div style="font-size:12px;color:var(--gold);font-weight:600;margin:8px 0;">🕯️ Finished</div>';
      h += '<div class="btn-hint" style="margin-bottom:10px;">' + chain.intro + '</div>';
      h += '<div class="btn-hint" style="margin-bottom:10px;">Five names, set down for good. There is nothing left here to come back for \u2014 and that is the point.</div>';
      h += '</div>';
      continue;
    }

    if (prog.cleared) {
      h += '<div style="font-size:12px;color:var(--gold);font-weight:600;margin:8px 0;">🏆 Complete \u2014 ' + (prog.clearCount || 1) + ' time' + ((prog.clearCount || 1) > 1 ? 's' : '') + '</div>';
      h += '<div class="btn-hint" style="margin-bottom:10px;">' + chain.intro + '</div>';
      h += '<div class="btn-hint" style="margin-bottom:10px;">Total chain payout: ' + totalXp.toLocaleString() + ' XP, ' + totalGold.toLocaleString() + 'G across ' + chain.stages.length + ' floors, every time.' + (hasScaledFloor ? ' The last floor scales with your level \u2014 always a real fight, no matter how far you\'ve climbed.' : '') + '</div>';
      h += '<button onclick="startChainQuest(\'' + chain.id + '\')" class="abtn" style="width:100%;">📜 Descend Again</button>';
      h += '</div>';
      continue;
    }

    h += '<div class="btn-hint" style="margin:8px 0;line-height:1.5;">' + chain.intro + '</div>';
    h += '<div class="qp" style="margin:10px 0;"><div class="pbar"><div class="pfill" style="width:' + Math.floor((prog.stageIndex / chain.stages.length) * 100) + '%"></div></div><span class="ptxt">Floor ' + prog.stageIndex + '/' + chain.stages.length + '</span></div>';

    if (prog.stageIndex > 0) {
      const nextStage = chain.stages[prog.stageIndex];
      const nextLocked = nextStage.minLevel && G.p.lvl < nextStage.minLevel;
      h += '<div class="btn-hint" style="margin-bottom:6px;">Next: ' + nextStage.title + (nextLocked ? ' (requires Level ' + nextStage.minLevel + ')' : '') + '</div>';
    }
    h += '<div class="btn-hint" style="margin-bottom:10px;">Total chain payout: ' + totalXp.toLocaleString() + ' XP, ' + totalGold.toLocaleString() + 'G across ' + chain.stages.length + ' floors.' + (hasScaledFloor ? ' The last floor scales with your level.' : '') + '</div>';

    h += '<button onclick="startChainQuest(\'' + chain.id + '\')" class="abtn" style="width:100%;">' + (prog.stageIndex > 0 ? '📜 Continue the Descent' : '📜 Begin the Descent') + '</button>';
    h += '</div>';
  }

  h += '</div>';
  return h;
}

function rEventDeck() {
  let h = '<div class="content">';
  h += '<div class="st" style="text-align:center;">📖 Daily Events</div>';

  // Detail/result view for one event
  if (G.activeEventId) {
    const eventDef = EVENT_DECK.find(e => e.id === G.activeEventId);
    const prog = (G.eventDeckProgress || {})[G.activeEventId];

    h += '<div class="panel panel-gold">';
    h += '<div class="panel-title" style="color:var(--gold);">' + eventDef.title + '</div>';
    h += '<div class="btn-hint" style="margin:10px 0;line-height:1.6;">' + eventDef.flavor + '</div>';

    if (prog) {
      h += '<div class="btn-hint" style="margin-bottom:6px;"><b>' + prog.choiceLabel + '</b></div>';
      if (prog.resultText) h += '<div class="btn-hint" style="margin-bottom:10px;line-height:1.6;">' + prog.resultText + '</div>';
      h += '<div style="font-size:16px;font-weight:700;color:var(--gold);margin-bottom:14px;">+' + prog.xp + ' XP, +' + prog.g + 'G</div>';
      h += '<button onclick="backToEventDeck()" class="abtn" style="width:100%;">Back to Today\'s Events</button>';
    } else {
      h += '<button onclick="resolveEventChoice(\'' + eventDef.id + '\', \'A\')" class="btn-outline-ghost" style="width:100%;text-align:left;margin-bottom:8px;">';
      h += eventDef.choiceA.label + '<br><span style="font-size:10px;opacity:0.7;">Guaranteed: +' + eventDef.choiceA.baseXp + ' XP, +' + eventDef.choiceA.baseG + 'G</span>';
      h += '</button>';
      h += '<button onclick="resolveEventChoice(\'' + eventDef.id + '\', \'B\')" class="btn-outline-ghost" style="width:100%;text-align:left;">';
      h += eventDef.choiceB.label + '<br><span style="font-size:10px;opacity:0.7;">' + eventDef.choiceB.stat.toUpperCase() + ' check \u2014 at least +' + eventDef.choiceB.baseXp + ' XP, +' + eventDef.choiceB.baseG + 'G, up to +' + (eventDef.choiceB.baseXp + eventDef.choiceB.bonusXp) + ' XP, +' + (eventDef.choiceB.baseG + eventDef.choiceB.bonusG) + 'G on success</span>';
      h += '</button>';
    }
    h += '</div>';
    h += '</div>';
    return h;
  }

  // List view
  const doneCount = (G.dailyEventDeck || []).filter(id => G.eventDeckProgress && G.eventDeckProgress[id]).length;
  h += '<div class="btn-hint" style="text-align:center;margin-bottom:16px;">A few short encounters, refreshed daily. Read, pick, done \u2014 no combat loop, nothing to grind. ' + doneCount + '/' + (G.dailyEventDeck || []).length + ' today.</div>';

  for (let eventId of (G.dailyEventDeck || [])) {
    const eventDef = EVENT_DECK.find(e => e.id === eventId);
    if (!eventDef) continue;
    const prog = (G.eventDeckProgress || {})[eventId];
    h += '<div class="card card-compact" onclick="openEvent(\'' + eventId + '\')" style="margin-bottom:10px;">';
    h += '<div class="panel-row"><div class="panel-title">' + eventDef.title + '</div>';
    if (prog) {
      h += '<div class="btn-hint" style="color:var(--gold);">✅ +' + prog.xp + ' XP</div>';
    } else {
      h += '<div class="btn-hint">Tap to begin \u2192</div>';
    }
    h += '</div></div>';
  }

  h += '</div>';
  return h;
}

function rRuneVault() {
  const rv = G.runeVault;
  let h = '<div class="content">';
  h += '<div class="st" style="text-align:center;">🔮 Rune Vault</div>';

  if (rv.completed) {
    h += '<div class="panel panel-gold" style="text-align:center;">';
    h += '<div class="panel-title" style="color:var(--gold);">' + rv.resultTier + '!</div>';
    h += '<div class="btn-hint" style="margin:8px 0;">Cleared in ' + rv.moves + ' moves</div>';
    h += '<div style="font-size:18px;font-weight:700;color:var(--gold);">+' + rv.resultXp + ' XP, +' + rv.resultG + 'G</div>';
    h += '</div>';
    h += '<div class="btn-hint" style="text-align:center;">One play per day \u2014 the vault reseals until tomorrow.</div>';
    h += '</div>';
    return h;
  }

  if (!rv.active) {
    const available = isRuneVaultAvailableToday();
    h += '<div class="btn-hint" style="text-align:center;margin-bottom:16px;">Match all 6 rune pairs in as few moves as possible. Purely skill \u2014 fewer moves, better reward. One free play per day.</div>';
    h += '<div class="panel">';
    h += '<div class="panel-title" style="margin-bottom:8px;">Reward Tiers</div>';
    h += '<div class="btn-hint" style="line-height:1.8;">🥇 Gold (\u226408 moves): 400 XP, 250G<br>🥈 Silver (\u226411 moves): 250 XP, 150G<br>🥉 Bronze (12+ moves): 130 XP, 80G</div>';
    h += '</div>';
    if (available) {
      h += '<button onclick="startRuneVault()" class="abtn" style="width:100%;">🔮 Open the Vault</button>';
    } else {
      h += '<div class="panel" style="text-align:center;"><div class="btn-hint">🔒 Already played today \u2014 come back tomorrow.</div></div>';
    }
    h += '</div>';
    return h;
  }

  // Active game — the grid
  h += '<div class="btn-hint" style="text-align:center;margin-bottom:12px;">Moves: ' + rv.moves + '</div>';
  h += '<div style="display:grid;grid-template-columns:repeat(4,1fr);gap:8px;max-width:340px;margin:0 auto;">';
  for (let i = 0; i < rv.cards.length; i++) {
    const card = rv.cards[i];
    const revealed = card.flipped || card.matched;
    h += '<div onclick="flipRuneCard(' + i + ')" style="aspect-ratio:1;display:flex;align-items:center;justify-content:center;font-size:28px;border-radius:10px;cursor:pointer;background:' + (card.matched ? 'rgba(251,191,36,0.15)' : 'var(--bg-hover)') + ';border:1px solid ' + (card.matched ? 'var(--gold)' : 'var(--border)') + ';user-select:none;">';
    h += revealed ? card.symbol : '❓';
    h += '</div>';
  }
  h += '</div>';

  h += '</div>';
  return h;
}

function rDragonHunt() {
  let h = '<div class="content">';
  h += '<div class="st" style="text-align:center;">🐉 Dragon Hunt</div>';
  h += '<div class="btn-hint" style="text-align:center;margin-bottom:16px;">Optional, legendary superbosses \u2014 no waves, no gimmicks, just a dragon with far more HP than anything else in the game. Repeatable.</div>';

  for (let dragon of DRAGONS) {
    const unlocked = isDragonUnlocked(dragon);
    const clearedCount = (G.dragonHunt.cleared && G.dragonHunt.cleared[dragon.id]) || 0;
    // Scaled dragons have no fixed hoard numbers — preview them live off the
    // player's current level so the card isn't just showing "undefined".
    const hoardMin = dragon.scaled ? getElderDragonStats(G.p.lvl).hoardGoldMin : dragon.hoardGoldMin;
    const hoardMax = dragon.scaled ? getElderDragonStats(G.p.lvl).hoardGoldMax : dragon.hoardGoldMax;

    h += '<div class="panel' + (unlocked ? ' panel-gold' : '') + '" style="text-align:center;">';
    const dragonArtFile = bossArtFileName(dragon.n);
    if (dragonArtFile) {
      h += '<div style="width:100%;max-width:220px;aspect-ratio:3/4;margin:0 auto 10px;border-radius:12px;overflow:hidden;border:2px solid ' + (unlocked ? 'var(--gold)' : 'var(--border)') + ';' + (unlocked ? '' : 'filter:grayscale(0.6) brightness(0.5);') + '">';
      h += '<img src="bosses/' + dragonArtFile + '.jpg" style="width:100%;height:100%;object-fit:cover;display:block;" onerror="this.parentElement.style.display=\'none\';">';
      h += '</div>';
    }
    h += '<div class="panel-title" style="' + (unlocked ? 'color:var(--gold);' : '') + '">' + dragon.n + '</div>';
    h += '<div class="btn-hint" style="margin:10px 0;line-height:1.5;">' + dragon.desc + '</div>';
    if (clearedCount > 0) {
      h += '<div style="font-size:12px;color:var(--gold);font-weight:600;margin-bottom:10px;">🏆 Slain ' + clearedCount + ' time' + (clearedCount > 1 ? 's' : '') + '</div>';
    }
    const mechanicDesc = dragon.mechanic === 'phase'
      ? 'Grows more dangerous through ' + dragon.phases + ' escalating phases as its HP drops \u2014 the fight gets harder, not easier, the longer it goes.'
      : dragon.mechanic === 'devour'
      ? 'Attempts to devour one random party member outright starting turn ' + dragon.devourTurn + ' \u2014 a failed save can remove them from the fight entirely.'
      : dragon.mechanic === 'apocalypse'
      ? 'Everyone survives to turn ' + dragon.apocalypseTurn + ', or almost no one does \u2014 a single attack that drops the whole party to the edge of death at once.'
      : 'Breathes elemental devastation across the whole party every ' + dragon.rampageTurn + ' turns.';
    h += '<div class="btn-hint" style="margin-bottom:10px;">' + mechanicDesc + ' Hoard on victory: ' + hoardMin.toLocaleString() + '\u2013' + hoardMax.toLocaleString() + 'G, 3 guaranteed Legendaries, 1 guaranteed Epic \u2014 on top of normal XP/gold.' + (dragon.scaled ? ' Scales with your level every fight \u2014 always a real fight, no matter how far you\'ve climbed.' : '') + '</div>';

    if (unlocked) {
      h += '<button onclick="startDragonHunt(\'' + dragon.id + '\')" class="abtn" style="width:100%;">🐉 Wake the Wyrm</button>';
    } else {
      h += '<div class="btn-hint">🔒 Unlocks at Level ' + dragon.unlockLevel + ' (currently Level ' + G.p.lvl + ')</div>';
    }
    h += '</div>';
  }

  h += '</div>';
  return h;
}

function rPrestige() {
  const unlocked = isPrestigeUnlocked();
  const projXp = +(G.p.lvl * PRESTIGE_XP_PCT_PER_LEVEL).toFixed(1);
  const projGold = +(G.p.lvl * PRESTIGE_GOLD_PCT_PER_LEVEL).toFixed(1);

  let h = '<div class="content">';
  h += '<div class="st" style="text-align:center;">🌟 Prestige</div>';
  h += '<div class="btn-hint" style="text-align:center;margin-bottom:16px;">Bank your level into a permanent bonus, then start the climb again \u2014 faster this time.</div>';

  h += '<div class="panel panel-gold" style="text-align:center;">';
  h += '<div class="panel-title" style="color:var(--gold);">Current Permanent Bonus</div>';
  h += '<div style="font-size:24px;font-weight:700;margin:8px 0;color:var(--gold);">+' + (G.prestige.xpBonusPct || 0).toFixed(1) + '% XP &nbsp;\u00b7&nbsp; +' + (G.prestige.goldBonusPct || 0).toFixed(1) + '% Gold</div>';
  h += '<div class="btn-hint">' + (G.prestige.count || 0) + ' prestige' + ((G.prestige.count || 0) === 1 ? '' : 's') + ' so far</div>';
  h += '<div class="btn-hint">Next prestige unlocks at Level ' + getPrestigeRequiredLevel() + '</div>';
  h += '</div>';

  h += '<div class="panel">';
  h += '<div class="panel-title" style="margin-bottom:8px;">🌟 Milestones</div>';
  h += '<div class="btn-hint" style="margin-bottom:10px;">Real, permanent rewards tied to how many times you\'ve done this \u2014 not just the stacking bonus above.</div>';
  const prestigeCount = G.prestige.count || 0;
  for (let m of PRESTIGE_MILESTONES) {
    const earned = prestigeCount >= m.count;
    h += '<div style="background:' + (earned ? 'color-mix(in srgb, var(--gold) 12%, transparent)' : 'var(--bg-hover)') + ';border:1px solid ' + (earned ? 'var(--gold)' : 'var(--border)') + ';border-radius:10px;padding:10px;margin-bottom:6px;' + (earned ? '' : 'opacity:0.55;') + '">';
    h += '<div style="font-weight:800;font-size:12px;color:' + (earned ? 'var(--gold)' : 'var(--text-dim)') + ';">' + (earned ? '✅' : '🔒') + ' ' + m.title + ' \u2014 ' + m.count + ' prestige' + (m.count === 1 ? '' : 's') + '</div>';
    h += '<div style="font-size:11px;color:var(--text-dim);margin-top:2px;">' + m.desc + '</div>';
    h += '</div>';
  }
  h += '</div>';

  h += '<div class="panel">';
  h += '<div class="panel-title" style="margin-bottom:8px;">What Happens</div>';
  h += '<div class="btn-hint" style="line-height:1.6;">Resets to Level 1: character level, XP, HP/MP pools, base stats, and mercenary tier.<br><br>Untouched: gold, gear, inventory, companions, story progress, quests, achievements, guild reputation, temple reputation, and Dragon Hunt clears.<br><br>Zones re-lock naturally since access is just your current level \u2014 you\'ll climb back through them, but every fight now pays out the bonus above, permanently, on top of whatever you bank today.</div>';
  h += '</div>';

  if (unlocked) {
    h += '<div class="panel" style="text-align:center;">';
    h += '<div class="btn-hint">Prestiging now at Level ' + G.p.lvl + ' banks:</div>';
    h += '<div style="font-size:18px;font-weight:700;margin:6px 0;color:var(--accent);">+' + projXp + '% XP &nbsp;\u00b7&nbsp; +' + projGold + '% Gold</div>';
    h += '</div>';
    h += '<button onclick="confirmPrestige()" class="abtn" style="width:100%;background:var(--danger);">🌟 Prestige Now (Level Resets to 1)</button>';
  } else {
    h += '<div class="panel" style="text-align:center;">';
    h += '<div class="btn-hint">🔒 Unlocks at Level ' + getPrestigeRequiredLevel() + ' (currently Level ' + G.p.lvl + ')</div>';
    h += '</div>';
  }

  h += '</div>';
  return h;
}

function confirmPrestige() {
  if (!isPrestigeUnlocked()) { doPrestige(); return; } // will just show the lock message
  if (confirm('Reset to Level 1 and bank the permanent bonus? Gear, gold, and story progress are kept \u2014 only level/XP/stats reset. This can\'t be undone.')) {
    doPrestige();
  }
}

function rBossRush() {
  const unlocked = isBossRushUnlocked();
  let h = '<div class="content">';
  h += '<div class="st" style="text-align:center;">💀 Boss Rush</div>';
  h += '<div class="btn-hint" style="text-align:center;margin-bottom:16px;">Random late-game bosses, back to back, no elite packs between \u2014 just a brief recovery. Every consecutive kill makes the next one tougher, but pays out better too. Push until you fall, or walk away with what you\'ve banked.</div>';

  h += '<div class="panel panel-gold" style="text-align:center;">';
  h += '<div class="panel-title" style="color:var(--gold);">Best Streak</div>';
  h += '<div style="font-size:24px;font-weight:700;margin:8px 0;color:var(--gold);">' + (G.bossRush.bestStreak || 0) + '</div>';
  h += '</div>';

  h += '<div class="panel">';
  h += '<div class="panel-title" style="margin-bottom:8px;">Per Kill</div>';
  h += '<div class="btn-hint" style="line-height:1.6;">+' + Math.floor(BOSS_RUSH_STAT_MULT_PER_KILL * 100) + '% boss stats \u00b7 +' + Math.floor(BOSS_RUSH_REWARD_MULT_PER_KILL * 100) + '% XP/gold (caps at +' + Math.floor((BOSS_RUSH_REWARD_MULT_CAP - 1) * 100) + '%)<br>' + Math.floor(BOSS_RUSH_RECOVERY_PCT * 100) + '% HP/MP recovery between fights \u2014 no full heals.</div>';
  h += '</div>';

  if (unlocked) {
    h += '<button onclick="startBossRush()" class="abtn" style="width:100%;background:var(--danger);">💀 Start the Rush</button>';
  } else {
    h += '<div class="panel" style="text-align:center;"><div class="btn-hint">🔒 Unlocks at Level ' + BOSS_RUSH_UNLOCK_LEVEL + ' (currently Level ' + G.p.lvl + ')</div></div>';
  }

  h += '</div>';
  return h;
}

function rKindlingNetwork() {
  ensureKindlingCommissionsCurrent();
  let h = '<div class="content">';
  h += '<div class="st" style="text-align:center;">🦊 The Kindling Network</div>';
  h += '<div class="btn-hint" style="text-align:center;margin-bottom:16px;">Other Kindled pairs, met along the way. Not a system to grind \u2014 just a record of who you have actually found out there.</div>';

  const linesLeft = 3 - G.kindlingCommissions.linesToday;
  const checksLeft = 2 - G.kindlingCommissions.checksToday;
  h += '<div class="panel" style="margin-bottom:16px;">';
  h += '<div class="panel-title" style="margin-bottom:8px;">Today\'s Small Practice</div>';
  h += '<button onclick="tendAKindlingLine()" ' + (linesLeft <= 0 ? 'disabled' : '') + ' class="btn-outline-ghost" style="width:100%;margin-bottom:8px;' + (linesLeft <= 0 ? 'opacity:0.5;' : '') + '">🕯️ Tend a Line (' + Math.max(0,linesLeft) + '/3 left today)</button>';
  h += '<button onclick="checkOnAKindlingPair()" ' + (checksLeft <= 0 ? 'disabled' : '') + ' class="btn-outline-ghost" style="width:100%;' + (checksLeft <= 0 ? 'opacity:0.5;' : '') + '">🦊 Check on a Pair (' + Math.max(0,checksLeft) + '/2 left today)</button>';
  h += '</div>';

  const knownEntries = KINDLING_NETWORK.filter(k => {
    const chEntry = G.storyJournal.entries.find(e => e.chapter === k.metChapter);
    return chEntry && G.storyJournal.unlocked.includes(chEntry.id);
  });

  if (knownEntries.length === 0) {
    h += '<div style="text-align:center;padding:40px;color:var(--text-dim);">No other Kindled pairs met yet.<br>The practice is bigger than you know. You just have not found the rest of it.</div>';
  } else {
    for (let k of knownEntries) {
      h += '<div class="zcard" style="border-color:var(--gold);">';
      h += '<div class="zh"><span class="zn">🦊 ' + k.name + '</span><span class="zl" style="color:var(--gold);">' + k.status + '</span></div>';
      h += '<div style="font-size:11px;color:var(--text-dim);margin:4px 0;">Bonded to ' + k.familiarType + ' \u00b7 Met in Chapter ' + k.metChapter + '</div>';
      h += '<div style="font-size:12px;line-height:1.6;color:var(--text);margin-top:6px;">' + k.desc + '</div>';
      h += '</div>';
    }
    h += '<div class="btn-hint" style="text-align:center;margin-top:12px;">' + knownEntries.length + ' of ' + KINDLING_NETWORK.length + ' known pairs found so far.</div>';
  }

  h += '</div>';
  return h;
}

