const ZONE_ICON_MAP = {
  'Whispering Woods': 'tree', 'Cursed Catacombs': 'skull', 'Crystal Caverns': 'crystal',
  'Ember Peak': 'volcano', 'Stormhold': 'storm', 'Frostspire Ruins': 'snowflake',
  'Sunken Temple': 'wave', 'Abyssal Depths': 'void', "Dragon's Maw": 'dragon',
  "Serpent's Coil": 'serpent', 'Starlight Spire': 'star', 'Arcane Planar Tower': 'tower',
  'The Shattered Veil': 'shard', 'Emberfall Dimension': 'flame', 'Frostbound Eternity': 'snowflake',
  "Stormcaller's Cradle": 'storm', 'The Fulcrum': 'portal', 'The Void Between': 'void',
  'Chronos Spire': 'clock', 'Aetherium Gardens': 'flower', 'The Convergence': 'portal',
  'The Nexus': 'nexusswirl', 'The Fractured Veil': 'shard', 'The Astral Maelstrom': 'cosmicswirl',
  'Infernal Crucible': 'flame', 'The Scorched Vein': 'volcano', 'Tidal Abyss': 'wave',
  'The Shattered Crown': 'crown', 'The Hollow Throne': 'throne', 'The Final Spire': 'star',
  'The Apex': 'peak', 'The Breaking': 'fracture', 'The Silent Ruin': 'ruins',
  'Ashfall Market': 'market', 'The Drowned Ledger': 'book', 'Rustbound Docks': 'anchor',
  "The Widow's Watch": 'lighthouse'
};

function getZoneIcon(zoneName) {
  const key = ZONE_ICON_MAP[zoneName] || 'default';
  return ZONE_ICON_SVGS[key] || ZONE_ICON_SVGS.default;
}

// Level ranges for the zone map tabs — one per Act, plus the original pre-Act content.
const ZONE_MAP_TABS = [
  { label: 'Main Story', min: 1, max: 29 },
  { label: 'Act I', min: 30, max: 35 },
  { label: 'Act II', min: 36, max: 40 },
  { label: 'Act III', min: 41, max: 45 },
  { label: 'Act IV', min: 46, max: 50 },
  { label: 'Act V: The Long Walk', min: 51, max: 55 },
];

// The Verdant Reach — level 56+, continuing directly from where "Where the Walk
// Leads" already left off ("There will be another one after it. That used to feel
// like a threat. It does not anymore."). Once unlocked, this REPLACES every tab
// above in normal Explore navigation; everything before becomes reachable only
// through Zul. Gated on having actually read the bridge chapter, not just hitting
// a level, so the transition lands with the story rather than silently on a number.
const VERDANT_REACH_TAB = { label: 'The Verdant Reach', min: 56, max: 200 };
const VERDANT_REACH_BRIDGE_CHAPTER = 'journal_069'; // "What the World Let Go Of" — comes after the 6 backstory chapters (62-67) and the charging/parents chapter (68). Written and live.

function hasEnteredVerdantReach() {
  return G.storyJournal.read.includes(VERDANT_REACH_BRIDGE_CHAPTER);
}

// Explore-tab-specific gate: the Verdant Reach tab should only REPLACE the low-level
// tabs while your current level actually justifies it. hasEnteredVerdantReach() alone
// is a permanent, one-way story flag — correct for retiring old-world strongholds
// forever, but wrong here, since Prestige resets G.p.lvl back to 1 without un-reading
// the bridge chapter. Without this extra level check, a post-prestige player at Lv 1
// would only ever see the Verdant Reach tab (56-200) with every single zone locked,
// and no tab left that shows anything they can actually reach.
function isInVerdantReachTabMode() {
  return hasEnteredVerdantReach() && G.p.lvl >= 56;
}

function getActiveZoneMapTabs() {
  return isInVerdantReachTabMode() ? [VERDANT_REACH_TAB] : ZONE_MAP_TABS;
}

function setExploreMapTab(idx) {
  G.exploreMapTab = idx;
  render();
}

function rExp(){
  let h='<div class="explore-view"><h2 class="st">Adventure Zones</h2>';
  h += rZoneMapTabs();
  h += rZoneMapView();
  h += '</div>';
  return h;
}

function rZoneMapTabs() {
  const tabs = getActiveZoneMapTabs();
  if (G.exploreMapTab === undefined || G.exploreMapTab >= tabs.length) G.exploreMapTab = 0;
  let h = '<div style="display:flex;gap:6px;overflow-x:auto;padding-bottom:8px;margin-bottom:8px;">';
  for (let i = 0; i < tabs.length; i++) {
    const tab = tabs[i];
    const sel = G.exploreMapTab === i;
    h += '<button onclick="setExploreMapTab(' + i + ')" class="tier-btn' + (sel ? ' sel' : '') + '" style="flex-shrink:0;">' + tab.label + '</button>';
  }
  h += '</div>';
  if (G.exploreMapTab === 0 && !isInVerdantReachTabMode()) {
    h += '<button onclick="setS(\'zone_map_starting_lands\')" class="btn-outline-ghost" style="width:100%;margin-bottom:8px;">\uD83D\uDDFA\uFE0F Starting Lands Map (1\u20139)</button>';
    h += '<button onclick="setS(\'zone_map_arcane_ascent\')" class="btn-outline-ghost" style="width:100%;margin-bottom:8px;">\uD83D\uDDFA\uFE0F Arcane Ascent Map (10\u201322)</button>';
    h += '<button onclick="setS(\'zone_map_elemental_wars\')" class="btn-outline-ghost" style="width:100%;margin-bottom:8px;">\uD83D\uDDFA\uFE0F Elemental Wars Map (23\u201330)</button>';
  }
  if (!isInVerdantReachTabMode() && G.exploreMapTab >= 1 && G.exploreMapTab <= 5) {
    h += '<button onclick="setS(\'zone_map_aftermath_roads\')" class="btn-outline-ghost" style="width:100%;margin-bottom:8px;">\uD83D\uDDFA\uFE0F The Aftermath Roads Map (30\u201355)</button>';
  }
  if (isInVerdantReachTabMode()) {
    h += '<div style="font-size:11px;color:var(--text-dim);margin-bottom:8px;">Everywhere before this is still there \u2014 Zul just drives now.</div>';
    h += '<button onclick="setS(\'zone_map_verdant_reach\')" class="btn-outline-ghost" style="width:100%;margin-bottom:8px;">\uD83D\uDDFA\uFE0F The Verdant Reach Map (56\u201395)</button>';
  }
  return h;
}

function rZoneMapView() {
  const tabs = getActiveZoneMapTabs();
  if (G.exploreMapTab === undefined || G.exploreMapTab >= tabs.length) G.exploreMapTab = 0;
  const range = tabs[G.exploreMapTab] || tabs[0];
  // Keep each zone's TRUE index into G.zones (not the filtered array's position) —
  // the click handler reads data-i to look up G.zones[i] directly.
  const zonesWithIndex = G.zones
    .map((z, i) => ({ z, i }))
    .filter(({ z }) => z.lv >= range.min && z.lv <= range.max);

  const spacingY = 110;
  const centerX = 150;
  const amplitude = 100;
  const height = zonesWithIndex.length * spacingY + 80;

  const points = zonesWithIndex.map((_, i) => ({
    x: Math.round(centerX + amplitude * Math.sin(i * 0.8)),
    y: 50 + i * spacingY
  }));

  let h = '<div style="position:relative;width:300px;max-width:100%;margin:0 auto;height:' + height + 'px;">';

  h += '<svg viewBox="0 0 300 ' + height + '" style="position:absolute;top:0;left:0;width:100%;height:100%;" preserveAspectRatio="none">';
  h += '<polyline points="' + points.map(p => p.x + ',' + p.y).join(' ') + '" fill="none" stroke="var(--border)" stroke-width="3" stroke-dasharray="6,6"/>';
  h += '</svg>';

  for (let idx = 0; idx < zonesWithIndex.length; idx++) {
    const { z, i } = zonesWithIndex[idx], p = points[idx];
    const lk = G.p.lvl < z.lv;
    const dc = z.dg=='low'?'var(--success)':z.dg=='medium'?'var(--gold)':z.dg=='high'?'var(--el-fire)':z.dg=='very high'?'var(--danger)':'var(--el-void)';
    const isBossZone = G.bosses.some(b => b.zone === z.n);
    h += '<div class="zcard map-node' + (lk ? ' locked' : '') + '" data-i="' + i + '" style="border-color:' + dc + ';background:radial-gradient(circle at 35% 30%, color-mix(in srgb, ' + dc + ' 20%, var(--bg-card)), var(--bg-card));left:' + p.x + 'px;top:' + p.y + 'px;" title="' + z.n + ' (Lv.' + z.lv + ')">';
    h += '<span class="map-node-icon">' + getZoneIcon(z.n) + '</span>';
    if (isBossZone) h += '<div class="map-node-boss">👑</div>';
    if (lk) h += '<div class="map-node-lock">🔒</div>';
    h += '</div>';
    h += '<div class="map-node-name" style="left:' + p.x + 'px;top:' + (p.y + 34) + 'px;">' + z.n + '</div>';
    h += '<div class="map-node-sub" style="left:' + p.x + 'px;top:' + (p.y + 46) + 'px;">' + (lk ? 'Lv.' + z.lv : 'Ready') + '</div>';
  }

  h += '</div>';
  return h;
}



function getStrongholdIdForRestSite(siteId) {
  for (let id in STRONGHOLDS) {
    if (STRONGHOLDS[id].restSiteIds && STRONGHOLDS[id].restSiteIds.includes(siteId)) return id;
  }
  return null;
}

// Rest site map — same winding-path visual language as the zone map, for consistency.
// Camps/taverns show their parent zone's own icon; temples and mana springs keep their
// distinct icons (⛪ / 💧) since those are meaningfully different kinds of stops, not just
// another camp in that zone.
function rRestSitesMap(healerOk) {
  const visibleSites = G.rest.sites.filter(s => {
    const zoneSiblings = G.rest.sites.filter(x => x.zone === s.zone);
    return zoneSiblings.some(x => x.unlocked);
  });
  if (visibleSites.length === 0) return '<div style="text-align:center;color:var(--text-dim);font-size:12px;padding:20px;">No rest sites discovered yet.</div>';

  const spacingY = 100, centerX = 150, amplitude = 90;
  const height = visibleSites.length * spacingY + 80;
  const points = visibleSites.map((s, i) => ({
    x: Math.round(centerX + amplitude * Math.sin(i * 0.8)),
    y: 50 + i * spacingY
  }));

  let h = '<div style="position:relative;width:300px;max-width:100%;margin:0 auto;height:' + height + 'px;">';
  h += '<svg viewBox="0 0 300 ' + height + '" style="position:absolute;top:0;left:0;width:100%;height:100%;" preserveAspectRatio="none">';
  h += '<polyline points="' + points.map(p => p.x + ',' + p.y).join(' ') + '" fill="none" stroke="var(--border)" stroke-width="3" stroke-dasharray="6,6"/>';
  h += '</svg>';

  for (let i = 0; i < visibleSites.length; i++) {
    const s = visibleSites[i], p = points[i];
    let manaSpringRemaining = 8;
    if (G.manaSpringUses.day === G.gameDay) manaSpringRemaining = 8 - G.manaSpringUses.count;
    const isDepletedManaSpring = s.type === 'mana_spring' && manaSpringRemaining <= 0;
    const ownerStrongholdId = s.stronghold ? getStrongholdIdForRestSite(s.id) : null;
    const isRetiredStronghold = ownerStrongholdId && STRONGHOLDS[ownerStrongholdId].era === 'oldWorld' && hasEnteredVerdantReach();
    const locked = !s.unlocked || isDepletedManaSpring || isRetiredStronghold;
    const canAfford = !s.cost || G.p.gold >= s.cost;

    const icon = (s.type === 'camp' || s.type === 'tavern') ? getZoneIcon(s.zone) : s.icon;
    const nodeColor = s.stronghold ? 'var(--gold)' : s.type === 'temple' ? 'var(--danger)' : s.type === 'mana_spring' ? 'var(--mp)' : 'var(--accent)';
    const subLabel = isRetiredStronghold ? 'Left behind'
      : locked
      ? (isDepletedManaSpring ? manaSpringRemaining + '/8 today' : 'Lv.' + s.zoneLv)
      : (s.cost ? s.cost + 'G' : 'Free');

    h += '<div class="rs-card map-node' + (locked ? ' locked' : '') + '" data-id="' + s.id + '" style="border-color:' + nodeColor + ';background:radial-gradient(circle at 35% 30%, color-mix(in srgb, ' + nodeColor + ' 20%, var(--bg-card)), var(--bg-card));left:' + p.x + 'px;top:' + p.y + 'px;' + (!canAfford && !locked ? 'opacity:0.6;' : '') + (isRetiredStronghold ? 'opacity:0.45;' : '') + '" title="' + s.name + (isRetiredStronghold ? ' \u2014 on the other side of the bridge now' : ' — ' + s.desc.replace(/"/g, '&quot;')) + '">';
    h += '<span class="map-node-icon">' + icon + '</span>';
    if (s.stronghold) h += '<div class="map-node-boss">🏰</div>';
    if (locked) h += '<div class="map-node-lock">🔒</div>';
    h += '</div>';
    h += '<div class="map-node-name" style="left:' + p.x + 'px;top:' + (p.y + 34) + 'px;">' + s.name + '</div>';
    h += '<div class="map-node-sub" style="left:' + p.x + 'px;top:' + (p.y + 46) + 'px;">' + subLabel + '</div>';
  }

  h += '</div>';
  h += '<div style="font-size:10px;color:var(--text-dim);text-align:center;margin-top:8px;">' + (healerOk ? '💚 Healer available' : '❌ No healer in party') + ' — tap a site to rest. Hold for details.</div>';
  return h;
}

// One distinct symbol per spell, replacing the old generic buff/damage-only icons
// (🛡️ for every buff, ⚡ for every damage spell) — the actual fix for combat feeling
// congested, since spells become scannable by shape/color instead of requiring the
// name to be read every time. Grouped by element below for consistency of feel.
// Optional chapter artwork — keyed by story-chapter title AND journal entry id, since
// "The Rain and the Kitten" exists in both the main storyline and the journal as the
// same scene. Most chapters have no entry here and simply render without an image;
