    for(let mi of matItems){
      const it = mi.item;
      const i = mi.index;
      h+='<div class="ic">';
      h+='<div class="ii">'+ie(it)+'</div>';
      h+='<div class="in" style="color:'+rc(it.r)+'">'+it.n+'</div>';
      h+='<div class="iq">x'+it.q+'</div>';
      h+='</div>';
    }
